'use strict';
/* ============================================================
   APEX — an ode to the Test match. Application.
   Everything below reads from the embedded archive; nothing writes to it.
   Same grammar as the motorsport odes: River · Grounds · Stage.
   ============================================================ */
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const A=window.ARCHIVE||JSON.parse(document.getElementById('archive-data').textContent);
const RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'—':Number.isInteger(n)?n.toLocaleString('en'):(Math.round(n*10)/10).toString();
const pct=(a,b)=>b?Math.round(a/b*1000)/10:0;
const day=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'—';
const dm=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}):'—';
const lum=hex=>{let m=/^#?([0-9a-f]{6})$/i.exec(hex||'');if(!m)return .5;let n=parseInt(m[1],16),r=(n>>16)/255,g=(n>>8&255)/255,b=(n&255)/255;const f=c=>c<=.03928?c/12.92:((c+.055)/1.055)**2.4;return .2126*f(r)+.7152*f(g)+.0722*f(b);};
const onColor=hex=>lum(hex)>.42?'#07080a':'#f4f4f2';
const mixHex=(a,b,t)=>{const p=h=>{const m=/^#?([0-9a-f]{6})$/i.exec(h);if(!m)return [128,128,128];const n=parseInt(m[1],16);return [n>>16,n>>8&255,n&255];};const x=p(a),y=p(b);return '#'+x.map((v,i)=>Math.round(v*t+y[i]*(1-t)).toString(16).padStart(2,'0')).join('');};
const hsl2hex=(h,s,l)=>{s/=100;l/=100;const k=n=>(n+h/30)%12,a=s*Math.min(l,1-l),f=n=>l-a*Math.max(-1,Math.min(k(n)-3,Math.min(9-k(n),1)));return '#'+[f(0),f(8),f(4)].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('');};

/* ---------- nations ---------- */
const TEN=A.teams, teamBy=Object.fromEntries(TEN.map(t=>[t.name,t])), TEN_NAMES=TEN.map(t=>t.name);
const OPP_COLOURS={'British & Irish Lions':'#e75863','Japan':'#f48f9a','Fiji':'#ecebe6','Samoa':'#618fff','Tonga':'#d65b5e','Georgia':'#a86572','Namibia':'#85a8ed','USA':'#b482a2','Portugal':'#d65965','South America':'#d6ba82','NZ Cavaliers':'#8faba3','World Invitation':'#c09aca','Canada':'#ef8d81','Romania':'#ecce59','Uruguay':'#8bcddd','Spain':'#c85a5b','Chile':'#d9705f','Germany':'#c9c2a0','Russia':'#c86a6a','Paraguay':'#d05a5a','Brazil':'#d7c95a','Zimbabwe':'#e0b45a','Czechia':'#7a8fd0','Morocco':'#c95c5c','Netherlands':'#f0a04b','Tunisia':'#d66a6a','Madagascar':'#6fb08a','Croatia':'#d46a7a','Ivory Coast':'#f0a860','Great Britain':'#9aa7d6'};
const CODES={'British & Irish Lions':'LIO','South America':'SAM','NZ Cavaliers':'CAV','World Invitation':'WXV','Great Britain':'GBR','USA':'USA','Czechia':'CZE','Ivory Coast':'CIV','Netherlands':'NED','Germany':'GER','Japan':'JPN','Fiji':'FIJ','Samoa':'SAM','Tonga':'TGA','Georgia':'GEO','Namibia':'NAM','Portugal':'POR','Canada':'CAN','Romania':'ROU','Uruguay':'URU','Spain':'ESP','Chile':'CHI','Russia':'RUS','Paraguay':'PAR','Brazil':'BRA','Zimbabwe':'ZIM','Morocco':'MAR','Tunisia':'TUN','Madagascar':'MAD','Croatia':'CRO'};
const hueCache={};
const NAT={};
function nat(n){if(NAT[n])return NAT[n];const t=teamBy[n];let color=t?t.accent:OPP_COLOURS[n];if(!color){let h=0;for(const ch of String(n))h=(h*31+ch.charCodeAt(0))>>>0;color=hsl2hex(h%360,35,60);}
  return NAT[n]={id:n,name:n,code:t?t.code:CODES[n]||n.replace(/[^A-Za-z]/g,'').slice(0,3).toUpperCase(),color,secondary:t?t.secondary:mixHex(color,'#f4f4f2',.5),kit:t?t.kit:color,trim:t?t.trim:color,nickname:t?t.nickname:'',tag:t?t.tag:'',titles:t?t.titles:[],ten:!!t};}
const color=n=>nat(n).color, code=n=>nat(n).code, tn=n=>n;
const teamVar=n=>`--team:${color(n)}`;

/* ---------- matches, seasons, grounds ---------- */
const isHomeFor=(m,side)=>m.country===side||(side==='Ireland'&&m.country==='Northern Ireland');
/* A side is counted for a match only where the archive recognises it for that side (the one exception is France v South Africa, 1907, recognised by France alone). */
const plays=(m,side)=>(m.home===side||m.away===side)&&(!teamBy[side]||m.eligible.includes(side));
const MATCHES=A.matches.map(m=>{const as=m.as_;const draw=m.hs===as;const winner=draw?null:m.hs>as?m.home:m.away;const loser=draw?null:winner===m.home?m.away:m.home;
  return {...m,as,draw,winner,loser,margin:Math.abs(m.hs-as),total:m.hs+as,recorded:!m.stadium.startsWith('ground-not-recorded'),points:m.scoreUnit!=='goals'};});
const byId=MATCHES;
const S=[];{const map={};for(const m of MATCHES){(map[m.year]||(map[m.year]={year:m.year,matches:[]})).matches.push(m);}for(const y of Object.keys(map).map(Number).sort((a,b)=>a-b))S.push(map[y]);}
const byYear=Object.fromEntries(S.map(s=>[s.year,s]));
const FIRST_YEAR=S[0].year,LAST_YEAR=S[S.length-1].year;
const GROUNDS={};for(const m of MATCHES){if(!m.recorded)continue;let g=GROUNDS[m.stadium]||(GROUNDS[m.stadium]={id:m.stadium,names:{},cities:{},countries:{}});g.names[m.venue]=(g.names[m.venue]||0)+1;if(m.city)g.cities[m.city]=(g.cities[m.city]||0)+1;if(m.country)g.countries[m.country]=(g.countries[m.country]||0)+1;}
for(const g of Object.values(GROUNDS)){const best=o=>Object.entries(o).sort((a,b)=>b[1]-a[1]||a[0].length-b[0].length)[0]?.[0]||'';g.name=Object.keys(g.names).sort((a,b)=>a.replace(/[^A-Za-z]/g,'').length-b.replace(/[^A-Za-z]/g,'').length||a.length-b.length)[0].replace(/[\s.\-]+$/,'');g.city=best(g.cities);g.country=best(g.countries);}
const groundName=id=>GROUNDS[id]?.name||(id.startsWith('ground-not-recorded')?'Ground not recorded':id);

/* ---------- players and coaches, linked to archive ids ---------- */
const perspIdx={};for(const t of TEN_NAMES)perspIdx[t]=MATCHES.filter(m=>m.eligible.includes(t)).map(m=>m.id);
const PLAYERS=A.players.map(p=>({...p,games:p.history.map(h=>({...h,mid:perspIdx[p.team]?.[h.match]??null})).filter(h=>h.mid!=null)}));
const playerBy=Object.fromEntries(PLAYERS.map(p=>[p.id,p]));
const COACHES=A.coaches.map(c=>({...c,matches:c.matchIds.map(i=>byId[i]).filter(Boolean)}));
const coachBy=Object.fromEntries(COACHES.map(c=>[c.id,c]));
const gamesByMatch={};for(const p of PLAYERS)for(const g of p.games){(gamesByMatch[g.mid]||(gamesByMatch[g.mid]=[])).push({p,g});}

/* ---------- eras ---------- */
const PTS=y=>({try:y>=1992?5:y>=1971?4:3,con:2,pen:3,drop:y>=1948?3:4,ptry:y>=2017?7:(y>=1992?5:y>=1971?4:3)});
const ERAS=[["origins","Early internationals",1871,1913,"The earliest internationals: the Home Nations from 1871, the first touring sides from the southern hemisphere, France from 1906. Before 1886 the archive counts goals rather than points."],
["interwar","Tours & interwar years",1914,1948,"Long tours by sea, the Five Nations resumed after each war, and international schedules with long gaps; the Springboks and All Blacks meet only on tour."],
["postwar","Post-war rugby",1949,1969,"Annual championships in Europe, tours of months rather than weeks, and the drop goal reduced to three points in 1948."],
["transition","Changing game",1970,1986,"The try rises to four points in 1971; South Africa’s isolation deepens; the first talk of a World Cup."],
["worldcup","World Cup beginnings",1987,1995,"The first three men’s Rugby World Cups, the five-point try from 1992, and the end of amateurism in 1995."],
["pro","Professional era",1996,2011,"The Tri Nations, the Six Nations with Italy from 2000, expanding November and June windows, and four more World Cups."],
["modern","Modern internationals",2012,2026,"The Rugby Championship with Argentina, the seven-point penalty try from 2017, and the most recent completed internationals."]].map(e=>({id:e[0],name:e[1],from:e[2],to:e[3],text:e[4]}));
const ERA_SHORT={origins:'Early internationals',interwar:'Tours · interwar',postwar:'Post-war',transition:'Changing game',worldcup:'World Cup begins',pro:'Professional',modern:'Modern'};
for(const e of ERAS){const a=PTS(e.from),b=PTS(e.to);const chip=(k,l)=>a[k]===b[k]?`${l} ${a[k]}`:`${l} ${a[k]} → ${b[k]}`;const feats=[e.from<1886?'Goals decide before 1886':null,chip('try','Try'),chip('con','Conversion'),chip('pen','Penalty'),chip('drop','Drop goal'),e.to>=2017?`Penalty try ${b.ptry}`:null].filter(Boolean);
  e.ball={label:'Scoring values of the era',features:feats,svg:ballSvg(e)};}
function ballSvg(e){const id='g'+e.id;return `<svg viewBox="0 0 300 150" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" x2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".9"/><stop offset="1" stop-color="var(--accent)" stop-opacity=".35"/></linearGradient></defs>
  <path d="M60 140V38M100 140V38M60 78h40" stroke="#cfd3da" stroke-width="5" stroke-linecap="round" fill="none"/><path d="M200 140V38M240 140V38M200 78h40" stroke="#cfd3da" stroke-width="5" stroke-linecap="round" fill="none" opacity=".35"/>
  <line x1="10" y1="140" x2="290" y2="140" stroke="#2e333d" stroke-width="2"/>
  <g transform="translate(150 70) rotate(-28)"><ellipse rx="46" ry="27" fill="url(#${id})" stroke="var(--accent)" stroke-width="2.5"/><path d="M-30 0h60M-18-8v16M-6-9v18M6-9v18M18-8v16" stroke="#07080a" stroke-width="2.5" stroke-linecap="round" opacity=".7"/></g>
  <text x="150" y="128" text-anchor="middle" font-family="JetBrains Mono,monospace" font-size="10" letter-spacing="2" fill="#8b9099">${e.from}–${e.to}</text></svg>`;}
const eraOf=y=>ERAS.find(e=>y>=e.from&&y<=e.to);

/* ---------- state ---------- */
const state={era:'all',year:LAST_YEAR,tab:'season',match:null,nation:null,player:null,ground:null,coach:null,lens:'wins',plens:'caps',heat:'rate',duelBy:'n',dA:null,dB:null,gridSort:'count',gridFind:'',gridMin:3,focusTeam:null,whole:false,find2:''};
const eraRange=()=>state.era==='all'?[FIRST_YEAR,LAST_YEAR]:(e=>[e.from,e.to])(ERAS.find(e=>e.id===state.era));
const inEraYear=y=>{const [a,b]=eraRange();return y>=a&&y<=b;};
const eraSeasons=()=>S.filter(s=>inEraYear(s.year));
const eraMatches=()=>eraSeasons().flatMap(s=>s.matches);
const eraLabel=()=>state.era==='all'?`All eras · ${FIRST_YEAR}–${LAST_YEAR}`:(e=>`${e.name} · ${e.from}–${e.to}`)(ERAS.find(e=>e.id===state.era));

/* ---------- aggregates ---------- */
function natStats(ms){const map={};for(const m of ms){for(const side of [m.home,m.away]){if(!plays(m,side))continue;const opp=side===m.home?m.away:m.home;const pf=side===m.home?m.hs:m.as,pa=side===m.home?m.as:m.hs;let a=map[side]||(map[side]={id:side,p:0,w:0,d:0,l:0,pf:0,pa:0,np:0,home:0,hw:0,first:m.year,last:m.year,grounds:new Set(),opps:new Set(),cups:0,big:null,streak:0,best:0,cur:0});
  a.p++;if(m.draw){a.d++;a.cur=0;}else if(m.winner===side){a.w++;a.cur++;if(a.cur>a.best)a.best=a.cur;}else{a.l++;a.cur=0;}if(m.points){a.pf+=pf;a.pa+=pa;a.np++;if(m.winner===side&&(!a.big||m.margin>a.big.margin))a.big=m;}if(isHomeFor(m,side)){a.home++;if(m.winner===side)a.hw++;}a.first=Math.min(a.first,m.year);a.last=Math.max(a.last,m.year);if(m.recorded)a.grounds.add(m.stadium);a.opps.add(opp);if(m.stage==='Final'&&m.winner===side)a.cups++;}}
  return Object.values(map).map(a=>({...a,rate:pct(a.w,a.p),ppm:a.np?Math.round(a.pf/a.np*10)/10:0,margin:a.np?Math.round((a.pf-a.pa)/a.np*10)/10:0,homeRate:pct(a.hw,a.home),streak:a.best}));}
const LENSES={wins:['Wins','Test matches won.'],rate:['Win rate %','Wins divided by all Tests, draws included. Minimum 10 Tests in the lens.'],p:['Tests','Matches played in the lens.'],pf:['Points for','Points scored; matches scored in goals (before 1886) are excluded.'],ppm:['Points per Test','Points for divided by points-era Tests. Minimum 10 Tests.'],margin:['Average margin','Points for minus points against, per points-era Test. Minimum 10 Tests.'],cups:['World Cups','Finals won.'],streak:['Longest winning run','Consecutive Test wins inside the lens.']};
const PLENSES={caps:['Caps','Test appearances, career totals as published.'],tries:['Tries','Career Test tries as published.'],points:['Points','Career Test points as published; unavailable for some careers.']};
const bestRecord=(ms,minP)=>{const st=natStats(ms);const maxP=Math.max(0,...st.map(a=>a.p));const min=Math.min(minP,maxP);return st.filter(a=>a.p>=min).sort((a,b)=>b.rate-a.rate||b.w-a.w||b.margin-a.margin)[0]||null;};
const seasonBest={};function champOf(s){if(seasonBest[s.year]!==undefined)return seasonBest[s.year];const b=bestRecord(s.matches,3);const final=s.matches.find(m=>m.stage==='Final');return seasonBest[s.year]={best:b,cup:final?{winner:final.winner,final}:null};}

/* ---------- theme ---------- */
function applyTheme(){let sel=$('#theme'),v=sel.value,root=document.documentElement,acc,sec,ter,ink;
  if(v==='champion'){const n=state.whole?bestRecord(eraMatches(),10)?.id:champOf(byYear[state.year]).best?.id;const t=n?nat(n):null;acc=t?t.color:'#5cd4a1';sec=t?t.secondary:'#e4bb65';ter=t?t.kit:'#006341';ink=onColor(acc);sel.options[0].textContent=`Best record’s colours · ${n||'—'}`;}
  else{const t=nat(v);acc=t.color;sec=t.secondary;ter=t.kit;ink=onColor(acc);}
  root.style.setProperty('--accent',acc);root.style.setProperty('--accent2',sec);root.style.setProperty('--accent3',ter);root.style.setProperty('--on-accent',ink);}

/* ---------- kick-off (the opening, once per visit) ---------- */
function lightsOut(){const box=$('#lights');let seen=false;try{seen=sessionStorage.getItem('apex-kickoff')==='1';}catch(e){}
  const out=()=>{if(!box.isConnected)return;box.classList.add('out');setTimeout(()=>box.remove(),800);try{sessionStorage.setItem('apex-kickoff','1');}catch(e){}};
  if(seen||RM){box.remove();return;}
  setTimeout(()=>box.classList.add('go'),400);setTimeout(()=>box.classList.add('over'),2300);setTimeout(out,3300);
  $('#skipLights').addEventListener('click',out);document.addEventListener('keydown',e=>{if(box.isConnected&&(e.key==='Enter'||e.key==='Escape'||e.key===' '))out();},{once:true});}

/* ---------- the River ---------- */
function smooth(pts){if(pts.length<3)return pts.map((p,i)=>(i?'L':'')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join('');let d='';for(let i=0;i<pts.length-1;i++){const p0=pts[i-1]||pts[i],p1=pts[i],p2=pts[i+1],p3=pts[i+2]||p2;const c1=[p1[0]+(p2[0]-p0[0])/6,p1[1]+(p2[1]-p0[1])/6],c2=[p2[0]-(p3[0]-p1[0])/6,p2[1]-(p3[1]-p1[1])/6];d+=`C${c1[0].toFixed(1)} ${c1[1].toFixed(1)} ${c2[0].toFixed(1)} ${c2[1].toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;}return d;}
let riverModel=null;
function buildRiver(){const years=S.map(s=>s.year),shares=[],totals=[],champs=[];const teamFirst={},teamTotal={};
  for(const s of S){const w={};let tot=0;for(const m of s.matches){if(m.draw){if(plays(m,m.home))w[m.home]=(w[m.home]||0)+.5;if(plays(m,m.away))w[m.away]=(w[m.away]||0)+.5;}else if(plays(m,m.winner))w[m.winner]=(w[m.winner]||0)+1;tot+=1;}
    for(const t in w){if(teamFirst[t]===undefined)teamFirst[t]=s.year;teamTotal[t]=(teamTotal[t]||0)+w[t];}
    const c=champOf(s);shares.push(w);totals.push(tot);champs.push({d:c.best?.id,t:c.best?.id,rec:c.best?`${c.best.w}–${c.best.l}–${c.best.d}`:'',cup:c.cup?.winner,races:s.matches.length});}
  const teams=Object.keys(teamFirst).sort((a,b)=>teamFirst[a]-teamFirst[b]||teamTotal[b]-teamTotal[a]);riverModel={years,shares,totals,champs,teams,teamTotal};}
function drawRiver(){
  if(!riverModel)buildRiver();const {years,shares,totals,champs,teams,teamTotal}=riverModel;
  const svg=$('#riverSvg'),box=svg.getBoundingClientRect(),W=Math.max(320,box.width),H=Math.max(200,box.height);svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
  const era=state.era==='all'?null:ERAS.find(e=>e.id===state.era);
  const i0=era?years.findIndex(y=>y>=era.from):0,i1=era?years.length-1-[...years].reverse().findIndex(y=>y<=era.to):years.length-1,n=i1-i0+1;
  const padL=8,padR=era?64:56,top=40,bottom=26,plotH=H-top-bottom;
  const slotW=n===1?(W-padL-padR)*.42:(W-padL-padR)/(n-1);const x=i=>n===1?padL+(W-padL-padR)/2:padL+(i-i0)*slotW;
  const maxRaces=Math.max(...champs.slice(i0,i1+1).map(c=>c.races));const thick=i=>plotH*(era?0.45+0.55*champs[i].races/maxRaces:0.22+0.78*champs[i].races/maxRaces);const y0=i=>top+(plotH-thick(i))/2;
  const cum=years.map(()=>0);let bands='';const eraTotal={};for(let i=i0;i<=i1;i++)for(const t in shares[i])eraTotal[t]=(eraTotal[t]||0)+shares[i][t];
  const drawTeams=era?teams.filter(t=>eraTotal[t]>0):teams;
  for(const t of drawTeams){const up=[],down=[];let any=false;for(let i=i0;i<=i1;i++){const sh=totals[i]?(shares[i][t]||0)/totals[i]:0;const a=y0(i)+cum[i]*thick(i);const b=a+sh*thick(i);cum[i]+=sh;up.push([x(i),a]);down.push([x(i),b]);if(sh>0)any=true;}if(!any)continue;
    if(n===1){const w=slotW/2;up.unshift([up[0][0]-w,up[0][1]]);up.push([up[1][0]+w,up[1][1]]);down.unshift([down[0][0]-w,down[0][1]]);down.push([down[1][0]+w,down[1][1]]);}
    const dn=down.reverse();const d='M'+up[0][0].toFixed(1)+' '+up[0][1].toFixed(1)+smooth(up)+'L'+dn[0][0].toFixed(1)+' '+dn[0][1].toFixed(1)+smooth(dn)+'Z';const tot=era?eraTotal[t]:teamTotal[t];
    bands+=`<path class="band${state.focusTeam===t?' focus':''}" data-t="${esc(t)}" d="${d}" fill="${color(t)}" stroke="#07080a" stroke-width=".5"><title>${esc(t)} · ${fmt(Math.round(tot))} wins ${era?'in this era':'since '+years[shares.findIndex(s=>s[t])]}</title></path>`;}
  let eras='';if(era){eras=`<text class="era-label" x="${padL}" y="${top-14}" style="fill:var(--accent)">${esc(era.name)} · ${era.from}–${era.to} · ${drawTeams.length} sides won a Test</text>`;}
  else for(const e of ERAS){const k=years.findIndex(y=>y>=e.from);if(k<0)continue;const xx=x(k);const nxt=ERAS[ERAS.indexOf(e)+1];const slot=(nxt?x(years.findIndex(y=>y>=nxt.from)):W)-xx;const label=ERA_SHORT[e.id]||e.name;const fits=label.length*6.6+8<=slot;eras+=`<line class="era-line" x1="${xx.toFixed(1)}" y1="${top-6}" x2="${xx.toFixed(1)}" y2="${H-bottom+4}"/>${fits?`<text class="era-label" x="${(xx+5).toFixed(1)}" y="${top-14}">${esc(label)}</text>`:''}`;}
  let strip='',hits='';for(let i=i0;i<=i1;i++){const w=slotW;strip+=`<rect x="${(x(i)-w/2).toFixed(1)}" y="${H-bottom+8}" width="${Math.max(1,w-1).toFixed(1)}" height="8" fill="${champs[i].t?color(champs[i].t):'#333'}" rx="1"><title>${years[i]} · best record ${esc(champs[i].d||'—')} ${champs[i].rec}${champs[i].cup?' · World Cup: '+esc(champs[i].cup):''}</title></rect>`;hits+=`<rect class="yearhit" data-y="${years[i]}" x="${(x(i)-w/2).toFixed(1)}" y="0" width="${w.toFixed(1)}" height="${H}"/>`;}
  const si=years.indexOf(state.year);const selX=n>1&&!state.whole&&si>=i0&&si<=i1?x(si):-10;
  svg.innerHTML=`<g id="bands">${bands}</g>${eras}<g>${strip}</g><line class="cursor" id="riverCursor" x1="0" y1="${top-4}" x2="0" y2="${H-bottom+4}"/><line x1="${selX.toFixed(1)}" y1="${top-4}" x2="${selX.toFixed(1)}" y2="${H-bottom+16}" stroke="var(--accent)" stroke-width="2" pointer-events="none"/><g id="hits">${hits}</g>`;
  $('#riverStage').classList.toggle('hasfocus',!!state.focusTeam);
  const axisYears=era?years.slice(i0,i1+1).filter((y,k,arr)=>arr.length<=14||k%Math.ceil(arr.length/12)===0||k===arr.length-1):[1871,1890,1910,1930,1950,1970,1990,2010,2026];
  $('#riverAxis').innerHTML=axisYears.map(y=>`<span>${y}</span>`).join('');
  const legend=$('#riverLegend');const scoreOf=era?eraTotal:teamTotal;const topN=[...drawTeams].sort((a,b)=>(scoreOf[b]||0)-(scoreOf[a]||0)).slice(0,14);if(state.focusTeam&&!(scoreOf[state.focusTeam]>0))state.focusTeam=null;
  legend.innerHTML=topN.map(t=>`<button type="button" data-t="${esc(t)}" class="${state.focusTeam===t?'on':''}"><i style="background:${color(t)}"></i>${esc(t)}</button>`).join('');
  if(!legend.dataset.built){legend.dataset.built='1';legend.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;state.focusTeam=state.focusTeam===b.dataset.t?null:b.dataset.t;drawRiver();});}
  const tip=$('#riverTip'),stage=$('#riverStage');
  svg.onmousemove=e=>{const hit=e.target.closest('.yearhit');if(!hit){tip.classList.remove('show');$('#riverCursor').style.opacity=0;return;}const y=+hit.dataset.y,i=years.indexOf(y);const cx=x(i);const cur=$('#riverCursor');cur.setAttribute('x1',cx);cur.setAttribute('x2',cx);cur.style.opacity=1;
    const top5=Object.entries(shares[i]).sort((a,b)=>b[1]-a[1]).slice(0,5);const c=champs[i];
    tip.innerHTML=`<div class="yr">${y}</div><div class="small muted" style="margin:2px 0 8px">${c.races} Tests · best record <b style="color:var(--ink)">${esc(c.d||'—')}</b> ${c.rec}${c.cup?` · <b style="color:var(--ink)">${esc(c.cup)}</b> world champions`:''}</div>${top5.map(([t,p])=>`<div class="row"><span><i class="sw" style="background:${color(t)}"></i>${esc(t)}</span><span>${totals[i]?Math.round(p/totals[i]*100):0}%</span></div>`).join('')}<div class="small dim" style="margin-top:8px">Share of all Tests won that year · click to open</div>`;
    const r=stage.getBoundingClientRect();let px=e.clientX-r.left;px=Math.max(150,Math.min(r.width-150,px));tip.style.left=px+'px';tip.style.top='12px';tip.classList.add('show');};
  svg.onmouseleave=()=>{tip.classList.remove('show');$('#riverCursor').style.opacity=0;};
  svg.onclick=e=>{const b=e.target.closest('.band');const hit=e.target.closest('.yearhit');if(hit){setSeason(+hit.dataset.y,true);}else if(b){state.focusTeam=state.focusTeam===b.dataset.t?null:b.dataset.t;drawRiver();}};
}

/* ---------- the Grounds (the Grid) ---------- */
function pitchOutline(opts={}){const ball=opts.ball&&!RM?`<g class="ball"><ellipse rx="16" ry="10" transform="rotate(-25)"/><animateMotion dur="7s" repeatCount="indefinite" begin="${opts.delay||0}s" path="M60 300 Q 250 90 440 300"/></g>`:'';
  return `<svg viewBox="0 0 500 500" aria-hidden="true" preserveAspectRatio="xMidYMid meet" class="pitch-o">${pitchLines()}${ball}</svg>`;}
/* one pitch, drawn from the same lines everywhere: goal lines at 68 and 432, 22s at 148 and 352, 10s dashed, halfway at 250 */
function pitchLines(tintL,tintR){return `<rect class="fld" x="20" y="135" width="460" height="230" rx="6"/><rect class="ig" x="20" y="135" width="48" height="230"${tintL?` style="fill:${tintL};opacity:.16"`:''}/><rect class="ig" x="432" y="135" width="48" height="230"${tintR?` style="fill:${tintR};opacity:.16"`:''}/><g class="ln">${[68,148,219,250,281,352,432].map(x=>`<line x1="${x}" y1="139" x2="${x}" y2="361"${x===219||x===281?' stroke-dasharray="8 8"':''}${x===250?' class="half"':''}/>`).join('')}<rect x="20" y="135" width="460" height="230" rx="6" class="edge"/></g><g class="posts"><path d="M68 190v120M46 190v120M46 262h22"/><path d="M432 190v120M454 190v120M432 262h22"/></g>`;}
function groundModel(){const ms=eraMatches();const m={};for(const r of ms){if(!r.recorded)continue;let c=m[r.stadium]||(m[r.stadium]={cid:r.stadium,count:0,first:r.year,last:r.year,wins:{},name:groundName(r.stadium),country:GROUNDS[r.stadium].country,place:GROUNDS[r.stadium].city});c.count++;c.first=Math.min(c.first,r.year);c.last=Math.max(c.last,r.year);if(r.winner)c.wins[r.winner]=(c.wins[r.winner]||0)+1;}
  return Object.values(m).map(c=>({...c,top:Object.entries(c.wins).sort((a,b)=>b[1]-a[1])[0]?.[0]||null}));}
function drawGrid(){const list=groundModel();const q=state.gridFind.trim().toLowerCase();const unrec=eraMatches().filter(m=>!m.recorded).length;let shown=list.filter(c=>(q||c.count>=state.gridMin)&&(!q||(c.name+' '+c.country+' '+c.place).toLowerCase().includes(q)));
  const sorters={count:(a,b)=>b.count-a.count||a.name.localeCompare(b.name),name:(a,b)=>a.name.localeCompare(b.name),country:(a,b)=>a.country.localeCompare(b.country)||b.count-a.count,recent:(a,b)=>b.last-a.last||b.count-a.count};shown.sort(sorters[state.gridSort]);
  const bigN=state.gridSort==='count'&&!q?6:0;
  $('#gridLede').textContent=`${list.length} grounds have staged a Test in ${eraLabel().replace(' · ',', ')}${unrec?`; ${unrec.toLocaleString('en')} more matches have no ground recorded`:''}. Each carries the colour of the nation that has won there most; the largest cards are the grounds Test rugby has returned to most often.${shown.length<list.length&&!q?` Showing ${shown.length} with ${state.gridMin}+ Tests.`:''}`;
  $('#circuits').innerHTML=shown.map((c,i)=>`<button type="button" class="circ flat${i<bigN?' big':''}" data-cid="${esc(c.cid)}" style="${c.top?teamVar(c.top):'--team:#8b9099'}" title="${esc(c.name)} · ${c.count} Tests · ${c.first}–${c.last}${c.top?' · most wins: '+esc(c.top):''}"><span class="ct">${esc(c.country)}${c.place&&c.place!==c.country?' · '+esc(c.place):''}</span><span class="n">${c.count}</span><span class="nm">${esc(c.name)}</span><span class="yrs">${c.first}${c.last!==c.first?'–'+c.last:''}${c.top?' · <i style="background:var(--team)"></i>'+esc(c.top)+' '+c.wins[c.top]:''}</span></button>`).join('')||`<p class="muted">No ground matches.</p>`;}

/* ---------- Stage: tabs, era strip, era context ---------- */
const TABS=[['season','Season'],['match','Match'],['nations','Nations'],['players','Players'],['grounds','Grounds'],['coaches','Coaches'],['records','Records'],['barcode','Barcode'],['duel','Duel']];
function drawTabs(){$('#tabs').innerHTML=TABS.map(([id,l])=>`<button type="button" role="tab" data-tab="${id}" aria-pressed="${state.tab===id}">${l}</button>`).join('');
  $('#stageStatus').textContent=(state.tab==='season'||state.tab==='match')&&!state.whole?`${state.year} · ${eraOf(state.year)?.name||''}`:eraLabel();}
function drawEraStrip(preview){const strip=$('#eraStrip');if(!strip.children.length)strip.innerHTML=ERAS.map(e=>`<button type="button" style="--w:${e.to-e.from+1}" data-era="${e.id}" title="${esc(e.name)} · ${e.from}–${e.to}" aria-label="${esc(e.name)} ${e.from}–${e.to}"></button>`).join('');
  for(const b of strip.children){b.classList.toggle('on',state.era===b.dataset.era);b.classList.toggle('demo',preview===b.dataset.era);}
  const e=preview?ERAS.find(x=>x.id===preview):state.era==='all'?eraOf(state.year):ERAS.find(x=>x.id===state.era);
  $('#eraCaption').innerHTML=`<span><b>${esc(e.name)}</b> · ${e.from}–${e.to}</span><span class="dim">${state.era===e.id?'Lens on · click again to release':'Click a segment to focus the whole page on that era'}</span>`;
  const ctx=$('#eraContext');ctx.innerHTML=`<div class="era-car">${e.ball.svg}</div><div><p class="eyebrow">${state.era===e.id?'Era lens':preview?'Era':'Era of the selected season'} · ${e.from}–${e.to}</p><h3>${esc(e.name)}</h3><p>${esc(e.text)}</p><div class="chips">${e.ball.features.map(f=>`<span>${esc(f)}</span>`).join('')}</div><p class="small dim" style="margin:10px 0 0">${esc(e.ball.label)} · as applied by this archive’s scoring table; a value with an arrow changed inside the era</p></div>`;}
const tour={i:-1,timer:null,visible:false,stopped:RM};
function tourStep(){if(tour.stopped||!tour.visible)return;tour.i=(tour.i+1)%ERAS.length;const ctx=$('#eraContext');ctx.classList.add('swap');setTimeout(()=>{if(tour.stopped)return;drawEraStrip(ERAS[tour.i].id);ctx.classList.remove('swap');},260);tour.timer=setTimeout(tourStep,4200);}
function tourStart(){if(tour.stopped||tour.timer)return;tour.timer=setTimeout(tourStep,1800);}
function tourPause(){clearTimeout(tour.timer);tour.timer=null;}
function tourStop(){if(tour.stopped)return;tour.stopped=true;tourPause();$('#eraContext').classList.remove('swap');drawEraStrip();}

/* ---------- shared pieces ---------- */
const resClass=(m,side)=>m.draw?'D':m.winner===side?'W':'L';
const scoreOf=(m,side)=>side===m.home?`${m.hs}–${m.as}`:`${m.as}–${m.hs}`;
const compShort=m=>m.worldcup?`RWC ${m.worldcup}${m.stage?' · '+m.stage:''}`:m.competition==='Six / Five / Home Nations'?'Championship':m.competition==='Rugby Championship / Tri Nations'?'Rugby Championship':m.competition==='Lions series'?'Lions':m.competition==='Historical / Olympic'?'Historical':m.competition==='Nations Championship'?'Nations Championship':'Test';
function matchCard(m,on){const w=m.winner;return `<button type="button" class="cal${on?' on':''}" data-match="${m.id}" style="${w?teamVar(w):'--team:#5b616b'}"><div class="rd">${esc(dm(m.date))} · ${esc(compShort(m))}${m.historical?' †':''}</div><div class="sc"><span>${esc(code(m.home))}</span><b>${m.hs}–${m.as}</b><span>${esc(code(m.away))}</span></div><div class="nm">${esc(m.home)} v ${esc(m.away)}</div><div class="w">${w?esc(w)+' won':'drawn'}${m.recorded?' · '+esc(groundName(m.stadium)):''}</div></button>`;}
function natBars(rows,valOf,subOf,max,unit=''){return `<div class="board">${rows.map((a,i)=>`<button type="button" class="bar" data-nation="${esc(a.id)}" style="--i:${i};${teamVar(a.id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(a.id)}<small> ${a.w}–${a.l}–${a.d}</small></span><small>${subOf(a)}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*valOf(a)/(max||1))}%"></span></span></span><span class="val">${valOf(a)}${unit}</span></button>`).join('')}</div>`;}
function drawChart(el,series,n,labelOf,xl){const box=el.getBoundingClientRect(),W=Math.max(300,box.width),H=Math.max(200,box.height);const padL=34,padR=110,padT=14,padB=26;const max=Math.max(1,...series.flatMap(s=>s.pts));const x=i=>padL+(n?i*(W-padL-padR)/n:0),y=v=>padT+(H-padT-padB)*(1-v/max);
  let g='';const step=max>200?100:max>60?25:max>20?10:max>8?5:1;for(let v=0;v<=max;v+=step)g+=`<line class="gridl" x1="${padL}" x2="${W-padR}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/><text class="lb" x="${padL-6}" y="${(y(v)+3).toFixed(1)}" text-anchor="end">${v}</text>`;
  for(let i=0;i<n;i++){const l=xl(i);if(l)g+=`<text class="lb" x="${x(i+1).toFixed(1)}" y="${H-8}" text-anchor="middle">${esc(l)}</text>`;}
  const paths=series.map(s=>{const d=s.pts.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)).join('');const last=s.pts[s.pts.length-1];return `<path class="ser" d="${d}" style="--c:${color(s.id)}"><title>${esc(labelOf(s.id))} · ${fmt(last)}</title></path><text class="end" x="${(x(n)+6).toFixed(1)}" y="${(y(last)+4).toFixed(1)}" style="--c:${color(s.id)}">${esc(labelOf(s.id))} ${fmt(last)}</text>`;}).join('');
  el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Cumulative wins">${g}${paths}</svg>`;}

/* ---------- Season ---------- */
function seasonView(){if(state.whole)return eraView();const s=byYear[state.year];const ms=s.matches;const st=natStats(ms);const maxP=Math.max(...st.map(a=>a.p));const ranked=st.filter(a=>a.p>=Math.min(3,maxP)).sort((a,b)=>b.rate-a.rate||b.w-a.w||b.margin-a.margin);const table=[...st].sort((a,b)=>b.rate-a.rate||b.w-a.w||b.margin-a.margin);
  const {best,cup}=champOf(s);const partial=String(s.year)===(A.through||'').slice(0,4);const nations=st.length,grounds=new Set(ms.filter(m=>m.recorded).map(m=>m.stadium)).size;
  const podium=ranked.slice(0,3);const order=[podium[1],podium[0],podium[2]];
  const head=`<div class="season-head"><div class="champ-card" style="${best?`--accent:${color(best.id)};--on-accent:${onColor(color(best.id))}`:''}"><p class="eyebrow" style="color:var(--ink);opacity:.7">${partial?'Season in progress · results through '+esc(day(A.through)):'Best record of the year'}</p><div class="yr">${s.year}</div>${best?`<div class="who"><small>${partial?'Leads the year':'Best record'} · ${best.w}–${best.l}–${best.d}</small>${esc(best.id)}</div><div class="team"><i></i>${esc(nat(best.id).nickname||nat(best.id).tag||'')}</div><div class="facts"><div><b>${best.rate}%</b>win rate</div><div><b>${best.p}</b>Tests</div><div><b>${ms.length}</b>Tests this year</div><div><b>${nations}</b>nations</div></div>`:'<div class="who">No results yet</div>'}${cup?`<p class="small" style="margin:18px 0 0;color:var(--ink);opacity:.85">World Cup: <b>${esc(cup.winner)}</b> beat ${esc(cup.final.loser)} ${esc(scoreOf(cup.final,cup.winner))} in the final</p>`:''}<p class="small dim" style="margin:${cup?6:18}px 0 0">Ranked by win rate, then wins, among sides with ${Math.min(3,maxP)}+ Tests in the year.</p></div>
  <div><div class="podium">${order.map((d,i)=>d?`<button type="button" class="step p${podium.indexOf(d)+1} bar" data-nation="${esc(d.id)}" style="--h:${Math.round(120+120*d.rate/100)}px;${teamVar(d.id)};display:flex"><span class="pos">${podium.indexOf(d)+1}</span><span class="nm">${esc(d.id)}</span><span class="pt">${d.w}–${d.l}–${d.d} · ${d.rate}% · ${d.p} Tests</span></button>`:'<div></div>').join('')}<div class="base"></div></div></div></div>`;
  const cal=`<div class="h3"><span>The year’s Tests</span><small>${ms.length} matches · click one to open it</small></div><div class="calendar">${ms.map(m=>matchCard(m,state.match===m.id&&state.tab==='match')).join('')}</div>`;
  const big=[...ms].filter(m=>m.points&&!m.draw).sort((a,b)=>b.margin-a.margin||b.total-a.total).slice(0,10);
  const body=`<div class="two" style="margin-top:26px"><div class="panel"><div class="h3"><span>Table of the year</span><small>every side that played · win rate, then wins</small></div>${natBars(table,a=>a.rate,a=>`${a.p} Tests · ${a.np?'avg margin '+(a.margin>0?'+':'')+a.margin:'goals era'}`,100,'%')}</div><div class="panel"><div class="h3"><span>Biggest wins of the year</span><small>by margin, points era</small></div><div class="board">${big.map((m,i)=>`<button type="button" class="bar" data-match="${m.id}" style="--i:${i};${teamVar(m.winner)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(m.winner)}<small> v ${esc(m.loser)}</small></span><small>${esc(dm(m.date))} · ${esc(compShort(m))}${m.recorded?' · '+esc(groundName(m.stadium)):''}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*m.margin/(big[0].margin||1))}%"></span></span></span><span class="val">${esc(scoreOf(m,m.winner))}</span></button>`).join('')||'<p class="muted small">No points-era results.</p>'}</div></div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>The year, Test by Test</span><small>cumulative wins, top ${Math.min(8,st.length)} sides</small></div><div class="chart" id="cumChart"></div></div>`;
  $('#view').innerHTML=head+cal+body;
  const top=[...st].sort((a,b)=>b.w-a.w||b.rate-a.rate).slice(0,8);const series=top.map(a=>({id:a.id,pts:[0]}));for(const m of ms)for(const sr of series)sr.pts.push(sr.pts[sr.pts.length-1]+(m.winner===sr.id?1:0));
  let lastMon='';drawChart($('#cumChart'),series,ms.length,x=>x,i=>{const mon=ms[i].date.slice(5,7);if(mon===lastMon)return '';lastMon=mon;return new Date(ms[i].date+'T12:00:00Z').toLocaleDateString('en-GB',{month:'short',timeZone:'UTC'});});}

/* ---------- Whole era, combined ---------- */
function eraView(){const seasons=eraSeasons();const ms=eraMatches();const e=state.era==='all'?null:ERAS.find(x=>x.id===state.era);const label=e?e.name:'All eras';const span=`${seasons[0].year}–${seasons[seasons.length-1].year}`;
  const st=natStats(ms);const ranked=st.filter(a=>a.p>=10).sort((a,b)=>b.rate-a.rate||b.w-a.w);const byWins=[...st].sort((a,b)=>b.w-a.w||b.rate-a.rate);
  const bests={};const roll=seasons.map(s=>{const c=champOf(s);if(c.best)bests[c.best.id]=(bests[c.best.id]||0)+1;return {year:s.year,d:c.best?.id,rec:c.best?`${c.best.w}–${c.best.l}–${c.best.d}`:'',cup:c.cup?.winner,n:s.matches.length};});
  const cups=ms.filter(m=>m.stage==='Final');const grounds=new Set(ms.filter(m=>m.recorded).map(m=>m.stadium)).size;
  const podium=ranked.slice(0,3);const order=[podium[1],podium[0],podium[2]];const top=ranked[0];
  const head=`<div class="season-head"><div class="champ-card" style="${top?`--accent:${color(top.id)};--on-accent:${onColor(color(top.id))}`:''}"><p class="eyebrow" style="color:var(--ink);opacity:.7">Whole era, combined · ${seasons.length} seasons</p><div class="yr" style="font-size:clamp(44px,6vw,84px)">${span}</div><div class="who"><small>${esc(label)} · best record</small>${esc(top?top.id:'—')}</div><div class="team"><i></i>${top?`${top.w}–${top.l}–${top.d} · ${top.rate}% of ${top.p} Tests`:''}</div><div class="facts"><div><b>${fmt(ms.length)}</b>Tests</div><div><b>${st.length}</b>sides</div><div><b>${grounds}</b>grounds</div><div><b>${cups.length}</b>World Cup finals</div></div><p class="small" style="margin:18px 0 0;color:var(--ink);opacity:.85">Most wins: <b>${esc(byWins[0]?.id||'—')}</b> · ${byWins[0]?.w||0} Tests won${Object.keys(bests).length?`<br><span class="dim">Best record of the year most often: ${esc(Object.entries(bests).sort((a,b)=>b[1]-a[1])[0][0])} (${Object.entries(bests).sort((a,b)=>b[1]-a[1])[0][1]} years)</span>`:''}</p></div>
  <div><div class="podium">${order.map(d=>d?`<button type="button" class="step p${podium.indexOf(d)+1} bar" data-nation="${esc(d.id)}" style="--h:${Math.round(120+120*d.rate/100)}px;${teamVar(d.id)};display:flex"><span class="pos">${podium.indexOf(d)+1}</span><span class="nm">${esc(d.id)}</span><span class="pt">${d.rate}% · ${d.w}–${d.l}–${d.d}</span></button>`:'<div></div>').join('')}<div class="base"></div></div></div></div>`;
  const rollHtml=`<div class="h3"><span>Best record, year by year</span><small>click a year to open it</small></div><div class="calendar">${roll.map(c=>`<button type="button" class="cal" data-year="${c.year}" style="${c.d?teamVar(c.d):'--team:#5b616b'}"><div class="rd">${c.year} · ${c.n} Tests</div><div class="nm" style="font-size:16px;margin-top:10px;color:var(--team)">${esc(c.d||'—')}</div><div class="w" style="color:var(--muted)">${c.rec}</div><div class="w">${c.cup?'⚑ '+esc(c.cup):''}</div></button>`).join('')}</div>`;
  const pl=PLAYERS.filter(p=>p.startYear<=seasons[seasons.length-1].year&&p.endYear>=seasons[0].year).sort((a,b)=>(b.caps||0)-(a.caps||0)).slice(0,20);
  const body=`<div class="two" style="margin-top:26px"><div class="panel"><div class="h3"><span>Nations across the era</span><small>by wins · ${st.length} sides</small></div>${natBars(byWins.slice(0,20),a=>a.w,a=>`${a.rate}% of ${a.p} Tests`,byWins[0]?.w)}</div><div class="panel"><div class="h3"><span>Careers across the era</span><small>most caps among careers overlapping ${span}</small></div><div class="board">${pl.map((p,i)=>`<button type="button" class="bar" data-player="${esc(p.id)}" style="--i:${i};${teamVar(p.team)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(p.name)}<small> ${esc(p.team)}</small></span><small>${esc(p.span)}${p.tries?' · '+p.tries+' tries':''}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*p.caps/(pl[0]?.caps||1))}%"></span></span></span><span class="val">${p.caps}</span></button>`).join('')}</div></div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Wins, season by season</span><small>cumulative Test wins, top ${Math.min(8,byWins.length)} by wins</small></div><div class="chart" id="cumChart"></div></div>`;
  $('#view').innerHTML=head+rollHtml+body;
  const series=byWins.slice(0,8).map(a=>({id:a.id,pts:[0]}));for(const s of seasons)for(const sr of series){let w=0;for(const m of s.matches)if(m.winner===sr.id)w++;sr.pts.push(sr.pts[sr.pts.length-1]+w);}
  drawChart($('#cumChart'),series,seasons.length,x=>x,i=>seasons.length<=20||i%Math.ceil(seasons.length/14)===0?String(seasons[i].year).slice(2):'');}
function eraMatchesView(){const ms=eraMatches();$('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Every Test · ${esc(eraLabel())}</span><small>${fmt(ms.length)} matches · click one to open it</small></div><div class="tablewrap"><table><tr><th>Date</th><th>Home</th><th>Score</th><th>Away</th><th>Competition</th><th>Ground</th></tr>${ms.slice().reverse().slice(0,1200).map(m=>`<tr><td><a href="#" data-match="${m.id}" style="color:inherit">${esc(day(m.date))}</a></td><td><i class="dot" style="${teamVar(m.home)}"></i>${esc(m.home)}</td><td><b>${m.hs}–${m.as}</b>${m.scoreUnit==='goals'?' <span class="dim">goals</span>':''}</td><td><i class="dot" style="${teamVar(m.away)}"></i>${esc(m.away)}</td><td>${esc(compShort(m))}${m.historical?' †':''}</td><td>${m.recorded?`<a href="#" data-ground="${esc(m.stadium)}" style="color:inherit">${esc(groundName(m.stadium))}</a>`:'<span class="dim">not recorded</span>'}</td></tr>`).join('')}</table></div>${ms.length>1200?`<p class="small dim">Showing the most recent 1,200 of ${fmt(ms.length)}; narrow the era lens or open a season for the rest.</p>`:''}`;}

/* ---------- Match: the sheet and the symbolic replay ---------- */
let replay=null;
function stopReplay(){if(replay){replay.timers.forEach(clearTimeout);replay=null;}}
function pitchEvents(m){const v=PTS(m.year);const mk=(side,off)=>{const ev=[];const push=(kind,n,pts)=>{for(let i=0;i<n;i++)ev.push({side,kind,pts});};if(m.scoring){const sc=m.scoring;push('try',sc[off],v.try);push('ptry',sc[off+5],v.ptry);push('con',sc[off+1],v.con);push('pen',sc[off+2],v.pen);push('drop',sc[off+3],v.drop);}
    else{/* no breakdown recorded: pace the scoreboard in plausible steps, drawn as plain marks */let rest=side==='home'?m.hs:m.as;while(rest>0){const step=rest>=v.try+v.con&&Math.random()<.6?v.try+v.con:rest>=v.try?v.try:rest>=v.pen?v.pen:rest;push('score',1,step);rest-=step;}}return ev;};
  const h=mk('home',0),a=mk('away',6);const out=[];let i=0,j=0;while(i<h.length||j<a.length){if(j>=a.length||(i<h.length&&i/h.length<=j/a.length))out.push(h[i++]);else out.push(a[j++]);}return out;}
function pitchSheet(m){const ev=pitchEvents(m);const hc=color(m.home),ac=color(m.away);let ch=0,ca=0,ih=0,ia=0;const known=!!m.scoring;
  const marks=ev.map((e,k)=>{const home=e.side==='home';const idx=home?ih++:ia++;const c=home?hc:ac;const y=150+((idx*37)%180);let x,shape;
    if(e.kind==='try'||e.kind==='ptry'){x=home?440+(idx*9)%30:60-(idx*9)%30;shape=`<ellipse cx="${x}" cy="${y}" rx="11" ry="7" fill="${e.kind==='ptry'?'none':c}" stroke="${c}" stroke-width="2.5" transform="rotate(-30 ${x} ${y})"/>`;}
    else if(e.kind==='con'){x=home?400-(idx*9)%40:100+(idx*9)%40;shape=`<path d="M${x} ${y+9}l7-18" stroke="${c}" stroke-width="3" fill="none"/><circle cx="${x+7}" cy="${y-9}" r="3" fill="${c}"/>`;}
    else if(e.kind==='pen'){x=home?330-(idx*13)%90:170+(idx*13)%90;shape=`<path d="M${x} ${y+10}v-20" stroke="${c}" stroke-width="3.5"/><path d="M${x-6} ${y-10}h12" stroke="${c}" stroke-width="3.5"/>`;}
    else if(e.kind==='drop'){x=home?370-(idx*15)%60:130+(idx*15)%60;shape=`<path d="M${x} ${y-9}l8 9-8 9-8-9z" fill="${c}"/>`;}
    else{x=home?250+40+(idx*23)%150:250-40-(idx*23)%150;shape=`<circle cx="${x}" cy="${y}" r="5" fill="${c}" opacity=".8"/>`;}
    if(home)ch+=e.pts;else ca+=e.pts;return `<g class="ev" data-k="${k}" data-h="${ch}" data-a="${ca}" style="animation-delay:${RM?0:k*.55+.4}s"><title>${esc(home?m.home:m.away)} · ${e.kind==='try'?'try':e.kind==='ptry'?'penalty try':e.kind==='con'?'conversion':e.kind==='pen'?'penalty goal':e.kind==='drop'?'drop goal':'score'} · +${e.pts}</title>${shape}</g>`;}).join('');
  return `<div class="replay" id="replay"><div class="hud"><div><h3>${esc(m.home)} v ${esc(m.away)}</h3><div class="sub">${esc(day(m.date))} · ${esc(compShort(m))}${m.recorded?' · '+esc(groundName(m.stadium)):''}</div></div><div class="whistle" aria-hidden="true">FT</div></div>
  <div class="track pitchwrap"><svg viewBox="0 120 500 260" class="pitch-o big" role="img" aria-label="Symbolic scoring map">${pitchLines(hc,ac)}<text x="26" y="357" class="igl">${esc(code(m.home))} in-goal</text><text x="474" y="357" class="igl" text-anchor="end">${esc(code(m.away))} in-goal</text><g id="pitchEvents">${marks}</g></svg></div>
  <div class="pitchscore"><span style="color:${hc}">${esc(m.home)}</span><b id="psH">0</b><i>–</i><b id="psA">0</b><span style="color:${ac}">${esc(m.away)}</span><button type="button" class="btn" id="pitchReplay">↻ Replay</button></div>
  <p class="small dim" style="margin:10px 0 0">${known?'A symbolic build of the scoreboard from the recorded breakdown — balls are tries (hollow: penalty tries), placed in the in-goal they were scored in; flags conversions, posts penalties, diamonds drop goals. The order of events is not recorded; the values are those of '+m.year+'.':'No scoring breakdown is recorded for this Test, so the scoreboard builds in symbolic steps of '+m.year+'’s values; the marks carry no meaning beyond pace.'}${m.scoreUnit==='goals'?' Scores before 1886 count goals.':''}</p></div>`;}
function runPitch(){stopReplay();const evs=$$('#pitchEvents .ev');const h=$('#psH'),a=$('#psA');if(!evs.length)return;const rp={timers:[]};replay=rp;const set=k=>{h.textContent=evs[k].dataset.h;a.textContent=evs[k].dataset.a;if(k===evs.length-1)$('#replay').classList.add('done');};
  const play=()=>{rp.timers.forEach(clearTimeout);rp.timers=[];$('#replay').classList.remove('done');evs.forEach(e=>{e.style.animation='none';e.offsetHeight;e.style.animation='';});h.textContent='0';a.textContent='0';evs.forEach((e,k)=>rp.timers.push(setTimeout(()=>set(k),RM?0:k*550+700)));};
  play();$('#pitchReplay').onclick=play;}
function h2hBefore(m){const ms=MATCHES.filter(x=>x.id<m.id&&plays(x,m.home)&&plays(x,m.away));const st=natStats(ms);const a=st.find(x=>x.id===m.home),b=st.find(x=>x.id===m.away);return {n:ms.length,a,b};}
function matchView(){if(state.whole)return eraMatchesView();const s=byYear[state.year];let m=byId[state.match];if(!m||m.year!==s.year)m=s.matches[s.matches.length-1];state.match=m.id;
  const nav=`<div class="chiplist" style="margin-top:20px">${s.matches.map(x=>`<button type="button" class="chip${x.id===m.id?' on':''}" data-match="${x.id}" style="${x.id===m.id?'border-color:var(--accent);color:var(--accent)':''}"><i style="--c:${x.winner?color(x.winner):'#444'}"></i>${esc(dm(x.date))} ${esc(code(x.home))}–${esc(code(x.away))}</button>`).join('')}</div>`;
  const line=side=>{const rows=(gamesByMatch[m.id]||[]).filter(x=>x.p.team===side).sort((p,q)=>(p.g.position==='Reserve')-(q.g.position==='Reserve')||p.p.name.localeCompare(q.p.name));if(!rows.length)return '';return `<div class="h3" style="margin-top:20px"><span>${esc(side)} · line-up</span><small>${rows.length} recorded appearances</small></div><div class="tower"><div class="th"><span>#</span><span></span><span>Player</span><span style="text-align:center"></span><span style="text-align:right"></span><span style="text-align:right">Tries</span><span style="text-align:right">Scoring</span></div>${rows.map((x,i)=>`<div class="tr" style="--i:${i};${teamVar(side)}"><span class="pos">${x.p.number||i+1}</span><span class="code">${esc(code(side))}</span><span class="name"><a href="#" data-player="${esc(x.p.id)}" style="color:inherit;text-decoration:none">${esc(x.p.name)}</a><small>${esc(x.g.position||'')}</small></span><span></span><span></span><span class="pts">${x.g.tries||''}</span><span class="st">${esc(x.g.scoring||'')}</span></div>`).join('')}</div>`;};
  const hh=h2hBefore(m);const form=side=>{const prev=MATCHES.filter(x=>x.id<m.id&&plays(x,side)).slice(-10);return `<div class="ribbon">${prev.map(x=>`<i class="${resClass(x,side)}" title="${esc(day(x.date))} v ${esc(x.home===side?x.away:x.home)} ${esc(scoreOf(x,side))}" data-match="${x.id}"></i>`).join('')}</div>`;};
  const side=`<div><div class="h3"><span>Before kick-off</span><small>the record between these two</small></div><div class="kpis" style="grid-template-columns:1fr 1fr"><div class="kpi" style="border-color:${color(m.home)}"><span>${esc(m.home)}</span><b>${hh.a?hh.a.w:0}</b><small>wins in ${hh.n} previous meetings${hh.a?' · form '+'':''}</small>${form(m.home)}</div><div class="kpi" style="border-color:${color(m.away)}"><span>${esc(m.away)}</span><b>${hh.b?hh.b.w:0}</b><small>wins in ${hh.n} previous meetings${hh.a&&hh.a.d?' · '+hh.a.d+' drawn':''}</small>${form(m.away)}</div></div><p class="small dim" style="margin:8px 0 0">Each side’s last ten Tests before this one: green won, red lost, grey drawn.</p>${line(m.home)}${line(m.away)}</div>`;
  const meta=`<div class="kpis" style="margin-top:18px"><div class="kpi"><span>Date</span><b style="font-size:22px">${esc(day(m.date))}</b><small>${m.dateUncertain?'date uncertain in source':esc(m.competitionRaw||'')}</small></div><div class="kpi"><span>Ground</span><b style="font-size:22px">${m.recorded?`<a href="#" data-ground="${esc(m.stadium)}" style="color:inherit;text-decoration:none">${esc(groundName(m.stadium))}</a>`:'Not recorded'}</b><small>${esc([m.city,m.country].filter(Boolean).join(', ')||'—')}</small></div><div class="kpi"><span>Competition</span><b style="font-size:22px">${esc(compShort(m))}</b><small>${esc(m.stage||m.competition)}${m.historical?' · historical recognition †':''}</small></div><div class="kpi"><span>Margin</span><b>${m.draw?'Draw':'+'+m.margin}</b><small>${m.draw?'':esc(m.winner)+' · '}${m.total} ${m.scoreUnit}</small></div><div class="kpi"><span>Nations</span><b style="font-size:22px"><a href="#" data-nation="${esc(m.home)}" style="color:inherit;text-decoration:none">${esc(code(m.home))}</a> · <a href="#" data-nation="${esc(m.away)}" style="color:inherit;text-decoration:none">${esc(code(m.away))}</a></b><small>open a nation</small></div></div>`;
  const links=`<p class="small dim" style="margin-top:14px">${(m.sources||[]).slice(0,3).map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(u.replace(/^https?:\/\//,'').split('/')[0])} ↗</a>`).join(' · ')}${m.notes&&m.notes.length?' · '+esc(m.notes.join(' ')):''}</p>`;
  $('#view').innerHTML=`${nav}<div class="race">${pitchSheet(m)}${side}</div>${meta}${links}`;runPitch();}

/* ---------- Nations ---------- */
function radar(el,axes,a,b){const W=260,H=260,cx=130,cy=130,R=96,n=axes.length;const pt=(i,v)=>{const ang=-Math.PI/2+i*2*Math.PI/n;return [cx+Math.cos(ang)*R*v,cy+Math.sin(ang)*R*v];};
  let g='';for(const k of [.25,.5,.75,1])g+=`<polygon class="ring" points="${axes.map((_,i)=>pt(i,k).map(v=>v.toFixed(1)).join(',')).join(' ')}"/>`;for(let i=0;i<n;i++){const [x,y]=pt(i,1);g+=`<line class="axis" x1="${cx}" y1="${cy}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}"/>`;const [lx,ly]=pt(i,1.24);g+=`<text class="lbl" x="${lx.toFixed(1)}" y="${(ly+3).toFixed(1)}">${esc(axes[i].label)}</text>`;}
  const poly=(vals,cls)=>`<polygon class="poly ${cls}" points="${vals.map((v,i)=>pt(i,Math.max(0,Math.min(1,v))).map(q=>q.toFixed(1)).join(',')).join(' ')}"/>`;el.innerHTML=`<svg viewBox="0 0 ${W} ${H}">${g}${poly(a,'a')}${b?poly(b,'b'):''}</svg>`;}
const AXES=[{k:'w',label:'Wins'},{k:'rate',label:'Win %'},{k:'p',label:'Tests'},{k:'ppm',label:'Pts / Test'},{k:'marginPos',label:'Margin'},{k:'homeRate',label:'Home %'},{k:'streak',label:'Best run'}];
function normAxes(list){const max={};for(const ax of AXES)max[ax.k]=Math.max(1,...list.map(a=>ax.k==='marginPos'?Math.max(0,a.margin):a[ax.k]));return a=>AXES.map(ax=>(ax.k==='marginPos'?Math.max(0,a.margin):a[ax.k])/max[ax.k]);}
function nationsView(){const ms=eraMatches();const list=natStats(ms);const lens=state.lens;const min=/rate|ppm|margin/.test(lens)?10:0;const rows=list.filter(a=>a.p>=min).sort((a,b)=>b[lens]-a[lens]||b.w-a.w).slice(0,30);const max=Math.max(1,...rows.map(a=>Math.abs(a[lens])));const q=(state.find2||'').toLowerCase();
  const found=q?list.filter(a=>a.id.toLowerCase().includes(q)).slice(0,12):[];
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Nations · ${esc(eraLabel())}</span><small>${list.length} sides · ${fmt(ms.length)} Tests</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px"><input type="search" id="find2" placeholder="Search a nation" value="${esc(state.find2||'')}" aria-label="Search"><select id="lens" aria-label="Lens">${Object.entries(LENSES).map(([k,v])=>`<option value="${k}" ${k===lens?'selected':''}>${v[0]}</option>`).join('')}</select><span class="small muted">${esc(LENSES[lens][1])}</span></div>${q?`<div class="chiplist" style="margin-bottom:14px">${found.map(a=>`<button type="button" class="chip" data-nation="${esc(a.id)}"><i style="--c:${color(a.id)}"></i>${esc(a.id)}</button>`).join('')||'<span class="muted small">No match.</span>'}</div>`:''}
  ${natBars(rows,a=>a[lens],a=>`${a.p} Tests · ${a.first}–${a.last}`,max,/rate/.test(lens)?'%':'')}</div>`;}
function seasonsTable(id){const out=[];for(const s of S){const ms=s.matches.filter(m=>plays(m,id));if(!ms.length)continue;const a=natStats(ms).find(x=>x.id===id);out.push({year:s.year,...a});}return out;}
function nationView(id){const ms=eraMatches();const all=natStats(ms);const a=all.find(x=>x.id===id);const back=`<button type="button" class="btn" data-tab="nations">← All nations</button>`;const t=nat(id);
  if(!a){$('#view').innerHTML=`<div style="margin-top:22px">${back}</div><p class="muted" style="margin-top:16px">${esc(id)} played no Test in ${esc(eraLabel())}. Change the era lens to see them.</p>`;return;}
  const mine=ms.filter(m=>plays(m,id));const norm=normAxes(all.filter(x=>x.p>=10));
  const ribbon=mine.map(m=>`<i class="${resClass(m,id)}" title="${esc(day(m.date))} v ${esc(m.home===id?m.away:m.home)} ${esc(scoreOf(m,id))}" data-match="${m.id}"></i>`).join('');
  const opp={};for(const m of mine){const o=m.home===id?m.away:m.home;let r=opp[o]||(opp[o]={id:o,p:0,w:0,d:0,l:0});r.p++;if(m.draw)r.d++;else if(m.winner===id)r.w++;else r.l++;}const opps=Object.values(opp).sort((a,b)=>b.p-a.p);
  const tbl=seasonsTable(id).filter(x=>inEraYear(x.year));const cups=mine.filter(m=>m.worldcup);const cupYears=[...new Set(cups.map(m=>m.worldcup))];const camp=cupYears.map(y=>{const cm=cups.filter(m=>m.worldcup===y);const last=cm[cm.length-1];const won=last.stage==='Final'&&last.winner===id;return {y,n:cm.length,w:cm.filter(m=>m.winner===id).length,last,won,exit:won?'Champions':last.stage==='Final'?'Runners-up':last.stage==='Bronze final'?(last.winner===id?'Third':'Fourth'):last.stage||'Pool'};});
  const coaches=COACHES.filter(c=>c.team===id&&c.endYear>=eraRange()[0]&&c.startYear<=eraRange()[1]);const players=PLAYERS.filter(p=>p.team===id&&p.endYear>=eraRange()[0]&&p.startYear<=eraRange()[1]).sort((a,b)=>(b.caps||0)-(a.caps||0)).slice(0,12);
  $('#view').innerHTML=`<div style="margin-top:22px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">${back}<span class="small muted">${esc(eraLabel())}</span></div>
  <div class="card" style="margin-top:18px;${teamVar(id)}"><div class="panel"><div class="trace" id="trace"></div><p class="small dim" style="text-align:center;margin:8px 0 0">Form trace · each axis relative to the best side in this era lens (10+ Tests)</p></div>
  <div><p class="eyebrow">${t.ten?'Nation':'Opponent'} · ${a.first}–${a.last}${t.nickname?' · '+esc(t.nickname):''}</p><h2 class="display" style="font-size:clamp(40px,6vw,84px);margin:6px 0 0;color:var(--team);text-shadow:0 0 30px rgba(255,255,255,.18)">${esc(id)}</h2>${t.tag?`<p class="muted" style="margin:4px 0 0">${esc(t.tag)}${t.titles.length?' · world champions '+t.titles.join(', '):''}</p>`:''}
  <div class="kpis" style="margin-top:18px"><div class="kpi"><span>Tests</span><b>${a.p}</b><small>${a.w}–${a.l}–${a.d}</small></div><div class="kpi"><span>Win rate</span><b>${a.rate}%</b><small>draws count as not won</small></div><div class="kpi"><span>Points</span><b>${fmt(a.pf)}</b><small>${fmt(a.pa)} against · ${a.np} points-era Tests</small></div><div class="kpi"><span>Avg margin</span><b>${a.margin>0?'+':''}${a.margin}</b><small>per points-era Test</small></div><div class="kpi"><span>At home</span><b>${a.homeRate}%</b><small>${a.hw} of ${a.home} home Tests</small></div><div class="kpi"><span>Best run</span><b>${a.streak}</b><small>consecutive wins</small></div><div class="kpi"><span>World Cups</span><b>${a.cups}</b><small>${camp.length} campaign${camp.length===1?'':'s'} in lens</small></div></div>
  <div class="h3" style="margin-top:20px"><span>Every Test</span><small>green won · red lost · grey drawn · click to open</small></div><div class="ribbon">${ribbon}</div>
  ${coaches.length?`<div class="h3" style="margin-top:20px"><span>Coaches</span></div><div class="chiplist">${coaches.map(c=>`<button type="button" class="chip" data-coach="${esc(c.id)}"><i style="--c:${color(id)}"></i>${esc(c.name)} <span class="dim">${esc(c.tenure)}</span></button>`).join('')}</div>`:''}</div></div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Record by opponent</span><small>most met first</small></div>${natBars(opps.slice(0,16),r=>r.w,r=>`${r.p} Tests · ${pct(r.w,r.p)}% won`,Math.max(1,...opps.map(r=>r.w)))}</div><div class="panel">${players.length?`<div class="h3"><span>Careers</span><small>most caps · careers overlapping the lens</small></div><div class="board">${players.map((p,i)=>`<button type="button" class="bar" data-player="${esc(p.id)}" style="--i:${i};${teamVar(id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(p.name)}<small> ${esc(p.position||'')}</small></span><small>${esc(p.span)}${p.tries?' · '+p.tries+' tries':''}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*p.caps/(players[0].caps||1))}%"></span></span></span><span class="val">${p.caps}</span></button>`).join('')}</div>`:''}${camp.length?`<div class="h3" style="margin-top:${players.length?16:0}px"><span>World Cup campaigns</span></div><div class="tablewrap"><table><tr><th>Year</th><th>Played</th><th>Won</th><th>Ended</th><th>Last match</th></tr>${camp.map(c=>`<tr><td>${c.y}</td><td>${c.n}</td><td>${c.w}</td><td>${c.won?'<b style="color:var(--gold)">Champions ★</b>':esc(c.exit)}</td><td><a href="#" data-match="${c.last.id}" style="color:inherit">${esc(scoreOf(c.last,id))} v ${esc(c.last.home===id?c.last.away:c.last.home)}</a></td></tr>`).join('')}</table></div>`:''}${!players.length&&!camp.length?'<p class="muted small">No career or World Cup records in this lens.</p>':''}</div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Season by season</span></div><div class="tablewrap"><table><tr><th>Year</th><th>P</th><th>W</th><th>D</th><th>L</th><th>Win %</th><th>For</th><th>Against</th><th>Best result</th></tr>${tbl.slice().reverse().map(x=>`<tr><td><a href="#" data-year="${x.year}" style="color:inherit">${x.year}</a></td><td>${x.p}</td><td>${x.w}</td><td>${x.d}</td><td>${x.l}</td><td>${x.rate}%</td><td>${x.np?x.pf:'—'}</td><td>${x.np?x.pa:'—'}</td><td>${x.big?`<a href="#" data-match="${x.big.id}" style="color:inherit">${esc(scoreOf(x.big,id))} v ${esc(x.big.home===id?x.big.away:x.big.home)}</a>`:'—'}</td></tr>`).join('')}</table></div></div>`;
  radar($('#trace'),AXES,norm(a));}

/* ---------- Players ---------- */
function playerPool(){if(state.era==='all')return PLAYERS;const [a,b]=eraRange();return PLAYERS.filter(p=>p.endYear>=a&&p.startYear<=b);}
function playersView(){const list=playerPool();const lens=state.plens;const rows=list.filter(p=>p[lens]!=null).sort((a,b)=>b[lens]-a[lens]||b.caps-a.caps).slice(0,40);const max=rows[0]?.[lens]||1;const q=(state.find2||'').toLowerCase();const found=q?list.filter(p=>p.name.toLowerCase().includes(q)).sort((a,b)=>b.caps-a.caps).slice(0,12):[];
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Players · ${esc(eraLabel())}</span><small>${list.length} careers overlapping the lens · ${PLAYERS.length} in the archive</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px"><input type="search" id="find2" placeholder="Search a player" value="${esc(state.find2||'')}" aria-label="Search"><select id="plens" aria-label="Lens">${Object.entries(PLENSES).map(([k,v])=>`<option value="${k}" ${k===lens?'selected':''}>${v[0]}</option>`).join('')}</select><span class="small muted">${esc(PLENSES[lens][1])} Career totals, not era totals: the lens selects careers by span.</span></div>${q?`<div class="chiplist" style="margin-bottom:14px">${found.map(p=>`<button type="button" class="chip" data-player="${esc(p.id)}"><i style="--c:${color(p.team)}"></i>${esc(p.name)}</button>`).join('')||'<span class="muted small">No match.</span>'}</div>`:''}
  <div class="board">${rows.map((p,i)=>`<button type="button" class="bar" data-player="${esc(p.id)}" style="--i:${i};${teamVar(p.team)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(p.name)}<small> ${esc(p.team)}${p.position?' · '+esc(p.position):''}</small></span><small>${esc(p.span)} · ${p.caps} caps</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*p[lens]/max)}%"></span></span></span><span class="val">${fmt(p[lens])}</span></button>`).join('')}</div><p class="small dim" style="margin:12px 0 0">Selected published career tables per nation, not every capped player; South Africa carries the fullest coverage.</p></div>`;}
function playerView(id){const p=playerBy[id];const back=`<button type="button" class="btn" data-tab="players">← All players</button>`;if(!p){$('#view').innerHTML=`<div style="margin-top:22px">${back}</div>`;return;}
  const games=p.games.map(g=>({...g,m:byId[g.mid]})).filter(g=>g.m);const inLens=games.filter(g=>inEraYear(g.m.year));const w=inLens.filter(g=>resClass(g.m,p.team)==='W').length;
  const byY={};for(const g of games){const y=g.m.year;byY[y]=byY[y]||{y,caps:0,tries:0,w:0};byY[y].caps++;byY[y].tries+=g.tries||0;if(resClass(g.m,p.team)==='W')byY[y].w++;}const years=Object.values(byY);const maxC=Math.max(1,...years.map(x=>x.caps));
  const opp={};for(const g of games){opp[g.opponent]=(opp[g.opponent]||0)+1;}const opps=Object.entries(opp).sort((a,b)=>b[1]-a[1]);
  $('#view').innerHTML=`<div style="margin-top:22px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">${back}<span class="small muted">${esc(eraLabel())}</span></div>
  <div class="card" style="margin-top:18px;grid-template-columns:1fr;${teamVar(p.team)}"><div><p class="eyebrow">Player · <a href="#" data-nation="${esc(p.team)}" style="color:inherit">${esc(p.team)}</a> · ${esc(p.span)}</p><h2 class="display" style="font-size:clamp(40px,6vw,84px);margin:6px 0 0;color:var(--team);text-shadow:0 0 30px rgba(255,255,255,.18)">${esc(p.name)}</h2><p class="muted" style="margin:4px 0 0">${esc(p.fullName&&p.fullName!==p.name.split(' ')[0]?p.fullName+' '+p.name.split(' ').slice(1).join(' ')+' · ':'')}${esc(p.position||'')}${p.dob?' · born '+esc(p.dob):''}${p.birthplace?', '+esc(p.birthplace):''}${p.number?' · Springbok no. '+esc(p.number):''}</p>
  <div class="kpis" style="margin-top:18px"><div class="kpi"><span>Caps</span><b>${p.caps}</b><small>career, as published</small></div>${p.tries!=null?`<div class="kpi"><span>Tries</span><b>${fmt(p.tries)}</b><small>career</small></div>`:''}${p.points!=null?`<div class="kpi"><span>Points</span><b>${fmt(p.points)}</b><small>career</small></div>`:''}${p.first?`<div class="kpi"><span>First Test</span><b style="font-size:22px">${esc(day(p.first))}</b></div><div class="kpi"><span>Last Test</span><b style="font-size:22px">${esc(day(p.last))}</b></div>`:`<div class="kpi"><span>Career span</span><b style="font-size:22px">${esc(p.span)}</b><small>years, as published</small></div>`}${games.length?`<div class="kpi"><span>Linked Tests</span><b>${games.length}</b><small>${p.complete?'complete history':'partial history'} · ${pct(games.filter(g=>resClass(g.m,p.team)==='W').length,games.length)}% won</small></div>`:''}</div>
  ${games.length?`<div class="h3" style="margin-top:20px"><span>Every linked Test</span><small>green won · red lost · grey drawn · click to open</small></div><div class="ribbon">${games.map(g=>`<i class="${resClass(g.m,p.team)}" title="${esc(day(g.m.date))} v ${esc(g.opponent)} ${esc(scoreOf(g.m,p.team))}${g.tries?' · '+g.tries+' tr':''}" data-match="${g.m.id}"></i>`).join('')}</div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Caps by year</span></div><div class="board">${years.map((x,i)=>`<div class="bar" style="--i:${i};${teamVar(p.team)};cursor:default"><span class="rk">${x.y}</span><span><span class="lab"><span>${x.caps} cap${x.caps===1?'':'s'}<small> ${x.w} won${x.tries?' · '+x.tries+' tries':''}</small></span></span><span class="trk"><span class="fill" style="--w:${Math.round(100*x.caps/maxC)}%"></span></span></span><span class="val">${x.caps}</span></div>`).join('')}</div></div><div class="panel"><div class="h3"><span>Opponents faced</span></div><div class="chiplist">${opps.map(([o,n])=>`<button type="button" class="chip" data-nation="${esc(o)}"><i style="--c:${color(o)}"></i>${esc(o)} <span class="dim">${n}</span></button>`).join('')}</div></div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Matches</span></div><div class="tablewrap"><table><tr><th>Date</th><th>Opponent</th><th>Score</th><th>Position</th><th>Scoring</th><th>Ground</th></tr>${games.slice().reverse().map(g=>`<tr><td><a href="#" data-match="${g.m.id}" style="color:inherit">${esc(day(g.m.date))}</a></td><td><i class="dot" style="${teamVar(g.opponent)}"></i>${esc(g.opponent)}</td><td><b class="${resClass(g.m,p.team)}">${esc(scoreOf(g.m,p.team))}</b></td><td>${esc(g.position||'')}</td><td>${esc(g.scoring||'')}</td><td>${g.m.recorded?esc(groundName(g.m.stadium)):'—'}</td></tr>`).join('')}</table></div></div>`:(()=>{const span=MATCHES.filter(m=>plays(m,p.team)&&m.year>=p.startYear&&m.year<=p.endYear);const a=natStats(span).find(x=>x.id===p.team);return `<p class="small dim" style="margin-top:16px">No match-by-match history is captured for this career; the totals above are the published snapshot.</p>${a?`<div class="h3" style="margin-top:20px"><span>${esc(p.team)} across this career</span><small>the nation’s record ${p.startYear}–${p.endYear}, not the player’s appearances</small></div><div class="kpis"><div class="kpi"><span>Tests</span><b>${a.p}</b><small>${a.w}–${a.l}–${a.d}</small></div><div class="kpi"><span>Win rate</span><b>${a.rate}%</b></div><div class="kpi"><span>Avg margin</span><b>${a.margin>0?'+':''}${a.margin}</b></div><div class="kpi"><span>World Cups</span><b>${a.cups}</b><small>won in the span</small></div></div><div class="ribbon" style="margin-top:12px">${span.map(m=>`<i class="${resClass(m,p.team)}" title="${esc(day(m.date))} v ${esc(m.home===p.team?m.away:m.home)} ${esc(scoreOf(m,p.team))}" data-match="${m.id}"></i>`).join('')}</div>`:''}`;})()}
  <p class="small dim" style="margin-top:12px">${(p.sources||[]).slice(0,3).map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(u.replace(/^https?:\/\//,'').split('/')[0])} ↗</a>`).join(' · ')}</p></div></div>`;}

/* ---------- Coaches ---------- */
function coachPool(){if(state.era==='all')return COACHES;const [a,b]=eraRange();return COACHES.filter(c=>c.endYear>=a&&c.startYear<=b);}
function coachesView(){const list=coachPool();const rows=list.slice().sort((a,b)=>(b.reported?.n||0)-(a.reported?.n||0)||b.startYear-a.startYear);const max=Math.max(1,...rows.map(c=>c.reported?.n||0));
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Coaches · ${esc(eraLabel())}</span><small>${list.length} tenures overlapping the lens · ${COACHES.length} in the archive</small></div><div class="panel"><div class="board">${rows.map((c,i)=>{const r=c.reported||{};return `<button type="button" class="bar" data-coach="${esc(c.id)}" style="--i:${i};${teamVar(c.team)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(c.name)}<small> ${esc(c.team)} · ${esc(c.tenure)}</small></span><small>${r.n!=null?`${r.w}–${r.l}–${r.d} · ${pct(r.w,r.n)}% won`:'record not published'}${c.role&&c.role!=='Head coach'?' · '+esc(c.role):''}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*(r.n||0)/max)}%"></span></span></span><span class="val">${r.n??'—'}</span></button>`;}).join('')}</div><p class="small dim" style="margin:12px 0 0">Published records from each union’s coaching list; where the archive could link the matches, the linked record is shown on the coach’s page. Coverage starts at different years per nation.</p></div>`;}
function coachView(id){const c=coachBy[id];const back=`<button type="button" class="btn" data-tab="coaches">← All coaches</button>`;if(!c){$('#view').innerHTML=`<div style="margin-top:22px">${back}</div>`;return;}const r=c.reported||{},l=c.linkedRecord;const ms=c.matches;
  $('#view').innerHTML=`<div style="margin-top:22px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">${back}<span class="small muted">${esc(eraLabel())}</span></div>
  <div class="card" style="margin-top:18px;grid-template-columns:1fr;${teamVar(c.team)}"><div><p class="eyebrow">${esc(c.role||'Coach')} · <a href="#" data-nation="${esc(c.team)}" style="color:inherit">${esc(c.team)}</a> · ${esc(c.tenure)}</p><h2 class="display" style="font-size:clamp(40px,6vw,84px);margin:6px 0 0;color:var(--team);text-shadow:0 0 30px rgba(255,255,255,.18)">${esc(c.name)}</h2>
  <div class="kpis" style="margin-top:18px"><div class="kpi"><span>Published record</span><b>${r.n!=null?`${r.w}–${r.l}–${r.d}`:'—'}</b><small>${r.n!=null?r.n+' Tests · '+pct(r.w,r.n)+'% won':'not published'}</small></div><div class="kpi"><span>Linked record</span><b>${l?`${l.w}–${l.l}–${l.d}`:'—'}</b><small>${l?l.n+' linked Tests':'no match linkage captured'}</small></div><div class="kpi"><span>Spells</span><b style="font-size:22px">${esc(c.spells.join(' · '))}</b></div><div class="kpi"><span>Method</span><b style="font-size:16px;font-style:normal;font-family:var(--body);font-weight:400;color:var(--muted)">${esc(c.method||'—')}</b></div></div>
  ${ms.length?`<div class="h3" style="margin-top:20px"><span>Every linked Test</span><small>green won · red lost · grey drawn</small></div><div class="ribbon">${ms.map(m=>`<i class="${resClass(m,c.team)}" title="${esc(day(m.date))} v ${esc(m.home===c.team?m.away:m.home)} ${esc(scoreOf(m,c.team))}" data-match="${m.id}"></i>`).join('')}</div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Matches</span></div><div class="tablewrap"><table><tr><th>Date</th><th>Opponent</th><th>Score</th><th>Competition</th><th>Ground</th></tr>${ms.slice().reverse().map(m=>`<tr><td><a href="#" data-match="${m.id}" style="color:inherit">${esc(day(m.date))}</a></td><td><i class="dot" style="${teamVar(m.home===c.team?m.away:m.home)}"></i>${esc(m.home===c.team?m.away:m.home)}</td><td><b class="${resClass(m,c.team)}">${esc(scoreOf(m,c.team))}</b></td><td>${esc(compShort(m))}</td><td>${m.recorded?esc(groundName(m.stadium)):'—'}</td></tr>`).join('')}</table></div></div>`:''}
  ${c.notes&&c.notes.length?`<p class="small muted" style="margin-top:12px">${esc(c.notes.join(' '))}</p>`:''}<p class="small dim" style="margin-top:12px">${(c.sources||[]).slice(0,2).map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(u.replace(/^https?:\/\//,'').split('/')[0])} ↗</a>`).join(' · ')}</p></div></div>`;}

/* ---------- Grounds ---------- */
function groundsView(){const list=groundModel().sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name));const unrec=eraMatches().filter(m=>!m.recorded).length;
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Grounds · ${esc(eraLabel())}</span><small>${list.length} venues${unrec?' · '+fmt(unrec)+' Tests without a recorded ground':''}</small></div><div class="tablewrap"><table><tr><th>Ground</th><th>City</th><th>Country</th><th>Tests</th><th>Years</th><th>Most wins</th></tr>${list.map(c=>`<tr><td><a href="#" data-ground="${esc(c.cid)}" style="color:inherit">${esc(c.name)}</a></td><td>${esc(c.place)}</td><td>${esc(c.country)}</td><td>${c.count}</td><td>${c.first}${c.last!==c.first?'–'+c.last:''}</td><td>${c.top?`<i class="dot" style="${teamVar(c.top)}"></i>${esc(c.top)} (${c.wins[c.top]})`:'—'}</td></tr>`).join('')}</table></div>`;}
function groundView(cid){const g=GROUNDS[cid];const ms=eraMatches().filter(m=>m.stadium===cid);const back=`<button type="button" class="btn" data-tab="grounds">← All grounds</button>`;
  if(!ms.length){$('#view').innerHTML=`<div style="margin-top:22px">${back}</div><p class="muted" style="margin-top:16px">${esc(g?.name||cid)} staged no Test in ${esc(eraLabel())}.</p>`;return;}
  const st=natStats(ms);const wins={};for(const m of ms)if(m.winner)wins[m.winner]=(wins[m.winner]||0)+1;const topW=Object.entries(wins).sort((a,b)=>b[1]-a[1]);const hostSide=st.filter(a=>ms.some(m=>isHomeFor(m,a.id))).sort((a,b)=>b.p-a.p)[0];
  const hi=[...ms].filter(m=>m.points).sort((a,b)=>b.total-a.total)[0];const big=[...ms].filter(m=>m.points&&!m.draw).sort((a,b)=>b.margin-a.margin)[0];const last=ms[ms.length-1];
  const ribbon=ms.map(m=>`<i style="--c:${m.winner?color(m.winner):'#333'}" title="${esc(day(m.date))} · ${esc(m.home)} ${m.hs}–${m.as} ${esc(m.away)}" data-match="${m.id}"></i>`).join('');
  $('#view').innerHTML=`<div style="margin-top:22px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">${back}<span class="small muted">${esc(eraLabel())}</span></div>
  <div class="card" style="margin-top:18px;grid-template-columns:1fr;${topW[0]?teamVar(topW[0][0]):''}">
  <div><p class="eyebrow">Ground · ${esc([g.city,g.country].filter(Boolean).join(', '))}</p><h2 class="display" style="font-size:clamp(36px,5.6vw,76px);margin:6px 0 0">${esc(g.name)}</h2>
  <div class="kpis" style="margin-top:18px"><div class="kpi"><span>Tests</span><b>${ms.length}</b><small>${ms[0].year}–${last.year}</small></div><div class="kpi"><span>Home side</span><b style="font-size:22px">${hostSide?esc(hostSide.id):'—'}</b><small>${hostSide?`${hostSide.w}–${hostSide.l}–${hostSide.d} here · ${hostSide.rate}%`:'neutral or unrecorded'}</small></div><div class="kpi"><span>Most wins</span><b style="font-size:22px">${topW[0]?esc(topW[0][0]):'—'}</b><small>${topW[0]?topW[0][1]+' of '+ms.length:''}</small></div><div class="kpi"><span>Highest aggregate</span><b>${hi?hi.total:'—'}</b><small>${hi?esc(hi.home)+' '+hi.hs+'–'+hi.as+' '+esc(hi.away)+' · '+hi.year:''}</small></div><div class="kpi"><span>Biggest margin</span><b>${big?'+'+big.margin:'—'}</b><small>${big?esc(big.winner)+' v '+esc(big.loser)+' · '+big.year:''}</small></div><div class="kpi"><span>Sides</span><b>${st.length}</b><small>have played here</small></div></div>
  <div class="h3" style="margin-top:20px"><span>Winners, Test by Test</span><small>one block per match, in the winner’s colour</small></div><div class="ribbon">${ribbon}</div></div></div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Most wins here</span></div>${natBars(topW.slice(0,8).map(([id,n])=>({id,w:n,l:st.find(a=>a.id===id).l,d:st.find(a=>a.id===id).d})),a=>a.w,a=>`${st.find(x=>x.id===a.id).p} Tests here`,topW[0]?.[1])}</div><div class="panel"><div class="h3"><span>Records here</span><small>by win rate, 3+ Tests</small></div>${natBars(st.filter(a=>a.p>=3).sort((a,b)=>b.rate-a.rate||b.w-a.w).slice(0,8),a=>a.rate,a=>`${a.p} Tests`,100,'%')||''}</div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Every Test here</span></div><div class="tablewrap"><table><tr><th>Date</th><th>Home</th><th>Score</th><th>Away</th><th>Competition</th></tr>${ms.slice().reverse().map(m=>`<tr><td><a href="#" data-match="${m.id}" style="color:inherit">${esc(day(m.date))}</a></td><td><i class="dot" style="${teamVar(m.home)}"></i>${esc(m.home)}</td><td><b>${m.hs}–${m.as}</b></td><td><i class="dot" style="${teamVar(m.away)}"></i>${esc(m.away)}</td><td>${esc(compShort(m))}${m.historical?' †':''}</td></tr>`).join('')}</table></div></div>`;}

/* ---------- Records ---------- */
function recordsView(){const ms=eraMatches();const st=natStats(ms);const pl=playerPool();const pts=ms.filter(m=>m.points);const grounds=new Set(ms.filter(m=>m.recorded).map(m=>m.stadium)).size;const cups=ms.filter(m=>m.stage==='Final');
  const big=[...pts].filter(m=>!m.draw).sort((a,b)=>b.margin-a.margin||b.total-a.total).slice(0,8);const hi=[...pts].sort((a,b)=>b.total-a.total||b.margin-a.margin).slice(0,8);const one=[...pts].filter(m=>m.winner).sort((a,b)=>Math.max(b.hs,b.as)-Math.max(a.hs,a.as))[0];
  const streaks=[...st].sort((a,b)=>b.streak-a.streak||b.rate-a.rate).slice(0,5);const draws=ms.filter(m=>m.draw).length;const nil=pts.filter(m=>m.hs===0&&m.as===0).length;
  const top=(k,min)=>{const rows=st.filter(a=>a.p>=min).sort((a,b)=>b[k]-a[k]||b.w-a.w).slice(0,5);return natBars(rows,a=>a[k],a=>`${a.p} Tests`,Math.max(1,...rows.map(a=>Math.abs(a[k]))),/rate/.test(k)?'%':'');};
  const ptop=k=>{const rows=pl.filter(p=>p[k]!=null).sort((a,b)=>b[k]-a[k]).slice(0,5);const max=rows[0]?.[k]||1;return `<div class="board">${rows.map((p,i)=>`<button type="button" class="bar" data-player="${esc(p.id)}" style="--i:${i};${teamVar(p.team)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(p.name)}<small> ${esc(code(p.team))} · ${esc(p.span)}</small></span></span><span class="trk"><span class="fill" style="--w:${Math.round(100*p[k]/max)}%"></span></span></span><span class="val">${fmt(p[k])}</span></button>`).join('')}</div>`;};
  const mlist=(arr,lab)=>`<div class="board">${arr.map((m,i)=>`<button type="button" class="bar" data-match="${m.id}" style="--i:${i};${teamVar(m.winner||m.home)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(m.home)} ${m.hs}–${m.as} ${esc(m.away)}</span><small>${esc(day(m.date))} · ${esc(compShort(m))}${m.recorded?' · '+esc(groundName(m.stadium)):''}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*lab(m)/(lab(arr[0])||1))}%"></span></span></span><span class="val">${lab(m)}</span></button>`).join('')}</div>`;
  const rec=(t,v,sub)=>`<div class="kpi"><span>${t}</span><b style="font-size:24px">${v}</b><small>${sub}</small></div>`;
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Records · ${esc(eraLabel())}</span><small>${fmt(ms.length)} Tests</small></div>
  <div class="kpis"><div class="kpi"><span>Tests</span><b>${fmt(ms.length)}</b><small>${eraSeasons().length} seasons · ${grounds} grounds</small></div><div class="kpi"><span>Sides</span><b>${st.length}</b><small>${st.filter(a=>nat(a.id).ten).length} of the ten nations</small></div><div class="kpi"><span>World Cup finals</span><b>${cups.length}</b><small>${[...new Set(cups.map(m=>m.winner))].length} different champions</small></div><div class="kpi"><span>Draws</span><b>${draws}</b><small>${pct(draws,ms.length)}% of Tests${nil?' · '+nil+' scoreless':''}</small></div><div class="kpi"><span>Careers</span><b>${pl.length}</b><small>published, overlapping the lens</small></div></div>
  <div class="kpis" style="margin-top:12px">${big[0]?rec('Biggest win',`+${big[0].margin}`,`${esc(big[0].winner)} ${esc(scoreOf(big[0],big[0].winner))} ${esc(big[0].loser)} · ${big[0].year}`):''}${hi[0]?rec('Highest aggregate',hi[0].total,`${esc(hi[0].home)} ${hi[0].hs}–${hi[0].as} ${esc(hi[0].away)} · ${hi[0].year}`):''}${one?rec('Most points by one side',Math.max(one.hs,one.as),`${esc(one.winner)} v ${esc(one.loser)} · ${one.year}`):''}${streaks[0]?rec('Longest winning run',streaks[0].streak,`${esc(streaks[0].id)} · consecutive Tests in lens`):''}</div>
  <div class="three" style="margin-top:20px"><div class="panel"><div class="h3"><span>Wins</span><small>nations</small></div>${top('w',0)}<div class="h3" style="margin-top:16px"><span></span><small>win rate · 20+ Tests</small></div>${top('rate',20)}</div><div class="panel"><div class="h3"><span>Points</span><small>points per Test · 20+</small></div>${top('ppm',20)}<div class="h3" style="margin-top:16px"><span></span><small>average margin · 20+</small></div>${top('margin',20)}</div><div class="panel"><div class="h3"><span>Careers</span><small>caps</small></div>${ptop('caps')}<div class="h3" style="margin-top:16px"><span></span><small>tries</small></div>${ptop('tries')}<div class="h3" style="margin-top:16px"><span></span><small>points</small></div>${ptop('points')}</div></div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Biggest wins</span><small>by margin</small></div>${mlist(big,m=>m.margin)}</div><div class="panel"><div class="h3"><span>Highest-scoring Tests</span><small>aggregate points</small></div>${mlist(hi,m=>m.total)}</div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Longest winning runs</span><small>consecutive Test wins inside the lens</small></div>${natBars(streaks,a=>a.streak,a=>`${a.p} Tests · ${a.rate}% won`,streaks[0]?.streak)}</div>`;}

/* ---------- Barcode ---------- */
const HEATMETRICS={rate:['Win rate %','Wins divided by Tests that year.'],w:['Wins','Tests won that year.'],p:['Tests','Matches played that year.'],pf:['Points for','Points scored that year, points era only.'],margin:['Average margin','Points for minus against, per Test.']};
function barcodeView(){const seasons=eraSeasons();const metric=state.heat;const per={};for(const s of seasons){for(const a of natStats(s.matches)){const v=metric==='margin'?Math.max(0,a.margin):a[metric];per[a.id]=per[a.id]||{id:a.id,cells:{},total:0,p:0};per[a.id].cells[s.year]=v;per[a.id].total+=metric==='rate'?a.w:v;per[a.id].p+=a.p;}}
  const rows=Object.values(per).sort((a,b)=>b.p-a.p).slice(0,28);const max=Math.max(1,...rows.flatMap(r=>Object.values(r.cells)));const years=seasons.map(s=>s.year);
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Season barcode · ${esc(eraLabel())}</span><small>${rows.length} sides × ${years.length} seasons</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px"><select id="heatMetric">${Object.entries(HEATMETRICS).map(([k,v])=>`<option value="${k}" ${k===metric?'selected':''}>${v[0]}</option>`).join('')}</select><span class="small muted">${esc(HEATMETRICS[metric][1])} Brightness is the cell’s share of the brightest cell; colour is the nation’s. Rows ordered by Tests played.</span></div>
  <div class="barcode"><div class="bc-row"><span></span><span class="cells" style="gap:2px">${years.map(y=>`<i style="background:none;height:14px;font-size:8px;color:var(--dim);text-align:center;line-height:14px">${years.length<=30||y%10===0?String(y).slice(2):''}</i>`).join('')}</span><span></span></div>${rows.map(r=>`<div class="bc-row"><span class="lab" data-nation="${esc(r.id)}">${esc(r.id)}</span><span class="cells">${years.map(y=>{const v=r.cells[y];const a=v===undefined?0:Math.max(.12,v/max);return `<i style="--c:${v===undefined?'#0e1014':mixHex(color(r.id),'#12141a',a)}" title="${y} · ${esc(r.id)} · ${v===undefined?'no Test':fmt(v)+(metric==='rate'?'%':'')}"></i>`;}).join('')}</span><span class="tot">${fmt(Math.round(r.total))}</span></div>`).join('')}</div>
  <div class="bc-key"><span><i style="--c:#0e1014"></i>no Test</span><span><i style="--c:#2a2f39"></i>low</span><span><i style="--c:var(--accent)"></i>high, in the nation’s colour</span><span class="dim">· row total: ${metric==='rate'?'wins':HEATMETRICS[metric][0].toLowerCase()}</span></div></div>`;}

/* ---------- Duel ---------- */
function swingChart(ms,a,b){const W=800,H=180,padL=30,padR=30,padT=16,padB=22;let cum=0;const pts=ms.map(m=>{cum+=m.winner===a?1:m.winner===b?-1:0;return cum;});const max=Math.max(1,...pts.map(Math.abs));const x=i=>padL+(ms.length>1?i*(W-padL-padR)/(ms.length-1):(W-padL-padR)/2),y=v=>padT+(H-padT-padB)*(1-v/max)/2;
  const d=pts.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)).join('');const zero=y(0);const area=`${d}L${x(ms.length-1).toFixed(1)} ${zero}L${x(0).toFixed(1)} ${zero}Z`;const cid='sw'+Math.random().toString(36).slice(2,7);
  return `<svg viewBox="0 0 ${W} ${H}" class="swing" role="img" aria-label="Cumulative lead in the rivalry"><defs><clipPath id="${cid}a"><rect x="0" y="0" width="${W}" height="${zero}"/></clipPath><clipPath id="${cid}b"><rect x="0" y="${zero}" width="${W}" height="${H-zero}"/></clipPath></defs><line x1="${padL}" x2="${W-padR}" y1="${zero}" y2="${zero}" stroke="#2e333d"/><text x="${padL}" y="${padT-4}" class="lb" fill="${color(a)}">${esc(a)} ahead</text><text x="${padL}" y="${H-6}" class="lb" fill="${color(b)}">${esc(b)} ahead</text><path d="${area}" fill="${color(a)}" opacity=".22" clip-path="url(#${cid}a)"/><path d="${area}" fill="${color(b)}" opacity=".22" clip-path="url(#${cid}b)"/><path d="${d}" fill="none" stroke="var(--ink)" stroke-width="1.6"/>${ms.map((m,i)=>`<circle cx="${x(i).toFixed(1)}" cy="${y(pts[i]).toFixed(1)}" r="3" fill="${m.winner?color(m.winner):'#8b9099'}" data-match="${m.id}" style="cursor:pointer"><title>${esc(day(m.date))} · ${esc(m.home)} ${m.hs}–${m.as} ${esc(m.away)}</title></circle>`).join('')}</svg>`;}
function duelView(){const by=state.duelBy;
  if(by==='p'){const pool=playerPool().sort((a,b)=>(b.caps||0)-(a.caps||0));if(!pool.find(p=>p.id===state.dA))state.dA=pool[0]?.id;if(!pool.find(p=>p.id===state.dB)||state.dB===state.dA)state.dB=pool.find(p=>p.id!==state.dA)?.id;const opt=v=>pool.map(p=>`<option value="${esc(p.id)}" ${p.id===v?'selected':''}>${esc(p.name)} (${esc(code(p.team))})</option>`).join('');const P1=playerBy[state.dA],P2=playerBy[state.dB];
    $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Head to head · ${esc(eraLabel())}</span><small>${pool.length} careers in lens</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px"><select id="duelBy"><option value="n">Nations</option><option value="p" selected>Players</option></select><select id="dA">${opt(state.dA)}</select><span class="eyebrow">vs</span><select id="dB">${opt(state.dB)}</select></div><div id="duelBody"></div></div>`;if(!P1||!P2)return;
    const rowsK=[['Caps','caps'],['Tries','tries'],['Points','points'],['First Test',null,p=>p.startYear],['Last Test',null,p=>p.endYear],['Linked Tests won %',null,p=>p.games.length?pct(p.games.filter(g=>byId[g.mid]&&resClass(byId[g.mid],p.team)==='W').length,p.games.length):null]];
    $('#duelBody').innerHTML=`<div class="two" style="gap:12px"><div class="kpi" style="border-color:${color(P1.team)}"><span>${esc(P1.name)}</span><b>${P1.caps}</b><small>caps · ${esc(P1.team)} · ${esc(P1.span)}</small></div><div class="kpi" style="border-color:${color(P2.team)}"><span>${esc(P2.name)}</span><b>${P2.caps}</b><small>caps · ${esc(P2.team)} · ${esc(P2.span)}</small></div></div>
    <div class="tablewrap" style="margin-top:14px"><table><tr><th style="text-align:right;color:${color(P1.team)}">${esc(P1.name)}</th><th></th><th style="color:${color(P2.team)}">${esc(P2.name)}</th></tr>${rowsK.map(([l,k,f])=>{const va=k?P1[k]:f(P1),vb=k?P2[k]:f(P2);const m=Math.max(va||0,vb||0,1);const bar=(v,c,right)=>v==null||/First|Last/.test(l)?'':`<span style="display:inline-block;height:8px;width:${Math.round(120*v/m)}px;background:${c};border-radius:2px;vertical-align:middle;margin-${right?'left':'right'}:8px"></span>`;return `<tr><td style="text-align:right">${bar(va,color(P1.team))}<b>${fmt(va)}</b></td><td style="text-align:center;color:var(--muted);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase">${l}</td><td><b>${fmt(vb)}</b>${bar(vb,color(P2.team),true)}</td></tr>`;}).join('')}</table></div><p class="small dim" style="margin-top:10px">Career totals as published; the linked-Tests figure exists only where a match-by-match history is captured.</p>`;return;}
  const ms=eraMatches();const all=natStats(ms).filter(a=>a.p>=5).sort((a,b)=>b.p-a.p);if(!all.find(a=>a.id===state.dA))state.dA=all[0]?.id;if(!all.find(a=>a.id===state.dB)||state.dB===state.dA)state.dB=all.find(a=>a.id!==state.dA&&ms.some(m=>plays(m,state.dA)&&plays(m,a.id)))?.id||all.find(a=>a.id!==state.dA)?.id;
  const opt=v=>all.map(a=>`<option value="${esc(a.id)}" ${a.id===v?'selected':''}>${esc(a.id)}</option>`).join('');const NA=all.find(a=>a.id===state.dA),NB=all.find(a=>a.id===state.dB);
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Head to head · ${esc(eraLabel())}</span><small>${all.length} sides with 5+ Tests</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px"><select id="duelBy"><option value="n" selected>Nations</option><option value="p">Players</option></select><select id="dA">${opt(state.dA)}</select><span class="eyebrow">vs</span><select id="dB">${opt(state.dB)}</select></div><div id="duelBody"></div></div>`;if(!NA||!NB)return;
  const meet=ms.filter(m=>plays(m,NA.id)&&plays(m,NB.id));const aw=meet.filter(m=>m.winner===NA.id).length,bw=meet.filter(m=>m.winner===NB.id).length,dr=meet.length-aw-bw;const bigA=[...meet].filter(m=>m.winner===NA.id&&m.points).sort((a,b)=>b.margin-a.margin)[0],bigB=[...meet].filter(m=>m.winner===NB.id&&m.points).sort((a,b)=>b.margin-a.margin)[0];
  const norm=normAxes(all);const rowsK=[['Wins','w'],['Win rate %','rate'],['Tests','p'],['Points per Test','ppm'],['Average margin','margin'],['Home win %','homeRate'],['Best run','streak'],['World Cups','cups']];
  $('#duelBody').innerHTML=`<div class="card" style="grid-template-columns:300px 1fr;--team:${color(NA.id)};--team2:${color(NB.id)}"><div class="trace" id="duelTrace"></div><div>
  <div class="two" style="gap:12px"><div class="kpi" style="border-color:${color(NA.id)}"><span>${esc(NA.id)}</span><b>${aw}</b><small>wins in ${meet.length} meetings${dr?' · '+dr+' drawn':''}${bigA?' · best '+esc(scoreOf(bigA,NA.id))+' ('+bigA.year+')':''}</small></div><div class="kpi" style="border-color:${color(NB.id)}"><span>${esc(NB.id)}</span><b>${bw}</b><small>wins in ${meet.length} meetings${bigB?' · best '+esc(scoreOf(bigB,NB.id))+' ('+bigB.year+')':''}</small></div></div>
  ${meet.length?`<div class="h3" style="margin-top:16px"><span>The rivalry, meeting by meeting</span><small>cumulative lead · click a point to open the match</small></div><div class="swingwrap">${swingChart(meet,NA.id,NB.id)}</div><div class="ribbon" style="margin-top:8px">${meet.slice(-30).map(m=>`<i class="${m.draw?'D':m.winner===NA.id?'W':'L'}" title="${esc(day(m.date))} · ${esc(m.home)} ${m.hs}–${m.as} ${esc(m.away)}" data-match="${m.id}"></i>`).join('')}</div><p class="small dim" style="margin:6px 0 0">Last ${Math.min(30,meet.length)} meetings from ${esc(NA.id)}’s side.</p>`:`<p class="muted small" style="margin-top:14px">These two have not met in ${esc(eraLabel())}.</p>`}
  <div class="tablewrap" style="margin-top:14px"><table><tr><th style="text-align:right;color:${color(NA.id)}">${esc(NA.id)}</th><th style="text-align:center"></th><th style="color:${color(NB.id)}">${esc(NB.id)}</th></tr>${rowsK.map(([l,k])=>{const va=NA[k],vb=NB[k];const m=Math.max(Math.abs(va),Math.abs(vb),1);return `<tr><td style="text-align:right"><span style="display:inline-block;height:8px;width:${Math.round(120*Math.max(0,va)/m)}px;background:${color(NA.id)};border-radius:2px;vertical-align:middle;margin-right:8px"></span><b>${fmt(va)}${/rate|Rate/.test(k)?'%':''}</b></td><td style="text-align:center;color:var(--muted);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase">${l}</td><td><b>${fmt(vb)}${/rate|Rate/.test(k)?'%':''}</b><span style="display:inline-block;height:8px;width:${Math.round(120*Math.max(0,vb)/m)}px;background:${color(NB.id)};border-radius:2px;vertical-align:middle;margin-left:8px"></span></td></tr>`;}).join('')}</table></div>
  <p class="small dim" style="margin-top:10px">Whole-lens figures for each side against everyone, not only against each other; the meetings count and the swing are head to head.</p></div></div>`;
  radar($('#duelTrace'),AXES,norm(NA),norm(NB));}

/* ---------- Sources & coverage ---------- */
function drawSources(){const kpi=(t,v,s)=>`<div class="kpi"><span>${t}</span><b>${v}</b><small>${s}</small></div>`;$('#sourcesBody').innerHTML=`<p class="eyebrow">Ten-nation edition / ${esc(day(A.asof))}</p><h2>One archive. Ten distinct records.</h2><div class="kpis">${kpi('Unique fixtures',fmt(A.matches.length),'shared records, each viewed from either side')}${kpi('Nations kept whole','10','every opponent remains in each archive')}${kpi('Career snapshots',fmt(A.players.length),'selected published records, not all players')}${kpi('Match span',`${FIRST_YEAR}–${LAST_YEAR}`,'latest captured match: '+esc(day(A.through)))}</div>
<h3>Why these ten?</h3><p class="small muted">South Africa, New Zealand, Australia, Argentina, England, France, Ireland, Wales, Scotland and Italy are the longstanding nations of the Rugby Championship and Six Nations. This is an editorial cohort, not an official all-time top-ten ranking. Fiji, Samoa, Japan, the Lions and other sides are retained as opponents and appear throughout the atlas; only Tests involving at least one of the ten are in the archive.</p>
<h3>Match records</h3><ol><li><a href="https://rugbyarchive.github.io/about.html" target="_blank" rel="noopener">Nuck’s Rugby Archive · historical match research</a><p>The principal source for the expanded national-team archive. Its public dataset combines reference books, union records and reporting. Fixtures marked as full internationals involving the ten selected nations were imported, awarded/abandoned fixtures excluded, and its uncertainty flags preserved. This is a curated independent archive, not a certified complete record from each union; the source itself identifies ongoing verification work.</p></li><li><a href="https://bokhist.com/StatOpponentSummary.aspx" target="_blank" rel="noopener">Springbok Rugby History · preserved South African record</a><p>All 577 match records, all 270 player snapshots, the captured player histories and eight World Cup squad lists from the previous edition are retained. The three conflicting dates against the Lions (1903), Australia (1992) and Australia (2021) follow this reconciled record. France’s 1907 fixture is present only from France’s perspective because it is absent from the Springbok capped archive.</p></li><li><a href="https://www.lassen.co.nz/pickandgo.php" target="_blank" rel="noopener">Pick &amp; Go · public latest-results cross-check</a><p>Public recent-result tables provide an additional cross-check. No restricted subscription records are included.</p></li></ol>
<h3>Player records</h3><p class="small muted">South African profiles retain their original detailed coverage: 98 captured appearance histories, of which 67 reconcile to career cap totals. The other nine nations have selected published career tables, primarily the linked national-team record pages, with primary-union checks where available. Each player has source links. Career snapshots can lag match results, and separate fields can have different update cut-offs. They are not a current squad list. Unknown values stay unavailable. The era lens selects careers by span; the totals shown are always career totals.</p>
<h3>Coaches</h3><p class="small muted">${Object.entries(A.coachCoverage).map(([n,c])=>`<b>${esc(n)}</b> from ${c.firstYear}, ${c.profiles} profiles, ${c.linked} linked matches. ${esc(c.note)}`).join(' ')} Coaching snapshot dated ${esc(day(A.coachAsOf))}.</p>
<h3>Recognition and early history</h3><p class="small muted">The archive includes source-classified internationals and retained historical capped fixtures; the latter are marked † in lists. Individual unions can recognise a match differently. France’s broader archive reaches the 1900 Olympics; its first standard Test is in 1906. The Springbok record includes 15 historical fixtures against South America, the NZ Cavaliers and World Invitation.</p>
<h3>Scores, eras and calculations</h3><p class="small muted">Win rate is wins divided by all matches, including draws. Before 1886 the archive’s numeric scores count goals; these fixtures contribute to results but are excluded from point sums, average margins and point-margin records. The River counts each Test win once, a draw as half to each side. “Best record of the year” ranks sides with at least three Tests that year (fewer only in the earliest years) by win rate, then wins, then average margin; it is a reading of the archive, not a title. Scoring values shown on the era card are those this atlas applies when it builds a symbolic scoreboard; historical changes in value are otherwise unadjusted. Grounds are recorded as the source gives them, so early fixtures often have none.</p>`;}

/* ---------- deep links: the address bar mirrors the state, so any view can be shared or opened from a static page ---------- */
let routeLock=false;
function writeRoute(){if(routeLock)return;const q=[];if(state.era!=='all')q.push('era='+encodeURIComponent(state.era));if(state.whole)q.push('whole=1');else q.push('season='+state.year);q.push('tab='+state.tab);if(state.tab==='match'&&!state.whole&&state.match!=null)q.push('match='+state.match);for(const k of ['nation','player','ground','coach']){if(state.tab===k+'s'&&state[k])q.push(k+'='+encodeURIComponent(state[k]));}const h='#'+q.join('&');if(location.hash!==h){try{history.replaceState(null,'',h);}catch(e){}}}
function readRoute(){const h=location.hash.replace(/^#\/?/,'');if(!h||/^static-/.test(h))return false;const p={};for(const kv of h.split('&')){const i=kv.indexOf('=');p[i<0?kv:kv.slice(0,i)]=i<0?'1':decodeURIComponent(kv.slice(i+1));}let any=false;
  if(p.era&&(p.era==='all'||ERAS.some(e=>e.id===p.era))){state.era=p.era;any=true;}
  if(p.match&&byId[+p.match]){state.match=+p.match;state.year=byId[+p.match].year;any=true;}else if(p.season&&byYear[+p.season]){state.year=+p.season;any=true;}
  if(state.era!=='all'&&!inEraYear(state.year)){if(p.season||p.match)state.era='all';else state.year=eraSeasons().slice(-1)[0].year;}
  state.whole=p.whole==='1';if(state.whole)any=true;
  if(p.tab&&TABS.some(t=>t[0]===p.tab)){state.tab=p.tab;any=true;}
  state.nation=p.nation&&NAT[p.nation]||p.nation&&MATCHES.some(m=>m.home===p.nation||m.away===p.nation)?p.nation:null;state.player=p.player&&playerBy[p.player]?p.player:null;state.ground=p.ground&&GROUNDS[p.ground]?p.ground:null;state.coach=p.coach&&coachBy[p.coach]?p.coach:null;
  if(!p.match||!byId[+p.match])state.match=byYear[state.year].matches.slice(-1)[0]?.id??null;
  return any;}
/* ---------- render, navigation, events ---------- */
function render(){stopReplay();drawTabs();if(tour.stopped||!tour.timer)drawEraStrip();const v={season:seasonView,match:matchView,nations:()=>state.nation?nationView(state.nation):nationsView(),players:()=>state.player?playerView(state.player):playersView(),grounds:()=>state.ground?groundView(state.ground):groundsView(),coaches:()=>state.coach?coachView(state.coach):coachesView(),records:recordsView,barcode:barcodeView,duel:duelView}[state.tab];try{v();}catch(e){$('#view').innerHTML=`<p class="muted">Something in this view could not be drawn: ${esc(e.message)}</p>`;console.error(e);}writeRoute();}
function go(tab,scroll=true){state.tab=tab;render();if(scroll)$('#stage').scrollIntoView({behavior:RM?'auto':'smooth',block:'start'});}
function ensureYearInLens(y){if(state.era!=='all'&&!inEraYear(y)){state.era='all';$('#eraSelect').value='all';drawGrid();}}
function setSeason(y,scroll){state.whole=false;ensureYearInLens(y);state.year=y;fillSeasons();state.match=byYear[y].matches.slice(-1)[0]?.id??null;applyTheme();drawRiver();if(state.tab!=='season'&&state.tab!=='match')state.tab='season';go(state.tab,scroll);}
function openMatch(id,scroll){const m=byId[id];if(!m)return;state.whole=false;ensureYearInLens(m.year);state.year=m.year;state.match=m.id;fillSeasons();applyTheme();drawRiver();go('match',scroll);}
function fillSeasons(){const sel=$('#season');const ss=eraSeasons();const e=state.era==='all'?null:ERAS.find(x=>x.id===state.era);sel.innerHTML=`<option value="era">${e?'Whole era':'All seasons'} · ${ss[0].year}–${ss[ss.length-1].year}</option>`+ss.slice().reverse().map(s=>`<option value="${s.year}">${s.year}</option>`).join('');sel.value=state.whole?'era':state.year;}
function setEra(id){tourStop();state.era=id;$('#eraSelect').value=id;if(id!=='all'){const e=ERAS.find(x=>x.id===id);if(!(state.year>=e.from&&state.year<=e.to)){state.year=eraSeasons().slice(-1)[0].year;state.match=byYear[state.year].matches.slice(-1)[0]?.id;}}fillSeasons();applyTheme();drawRiver();drawGrid();render();}
function init(){
  $('#eraSelect').innerHTML=`<option value="all">All eras · ${FIRST_YEAR}–${LAST_YEAR}</option>`+ERAS.map(e=>`<option value="${e.id}">${esc(e.name)} · ${e.from}–${e.to}</option>`).join('');
  $('#theme').innerHTML=`<option value="champion">Best record’s colours</option>`+TEN.map(t=>`<option value="${esc(t.name)}">${esc(t.name)} · ${esc(t.nickname)}</option>`).join('');
  fillSeasons();
  const sides=new Set(MATCHES.flatMap(m=>[m.home,m.away])).size;
  $('#edition').innerHTML=`<span><span class="live"></span><b>${fmt(MATCHES.length)}</b> Test matches</span><span><b>${sides}</b> sides</span><span><b>${Object.keys(GROUNDS).length}</b> grounds</span><span><b>${PLAYERS.length}</b> careers</span><span><b>${COACHES.length}</b> coaches</span><span>through <b>${esc(day(A.through))}</b></span>`;
  $('#reading').open=false;state.match=byYear[state.year].matches.slice(-1)[0]?.id;
  const deep=readRoute();if(deep){tourStop();$('#eraSelect').value=state.era;fillSeasons();}
  drawSources();applyTheme();drawRiver();drawGrid();render();lightsOut();if(deep&&(state.tab!=='season'||state.whole||state.era!=='all'))setTimeout(()=>$('#stage').scrollIntoView({behavior:'auto',block:'start'}),60);
  addEventListener('hashchange',()=>{if(/^#static-/.test(location.hash)){$('#reading').open=true;return;}routeLock=true;try{if(readRoute()){tourStop();$('#eraSelect').value=state.era;fillSeasons();applyTheme();drawRiver();drawGrid();render();}}finally{routeLock=false;}});
  $('#eraSelect').addEventListener('change',e=>setEra(e.target.value));
  $('#season').addEventListener('change',e=>{if(e.target.value==='era'){state.whole=true;applyTheme();drawRiver();if(state.tab!=='season'&&state.tab!=='match')state.tab='season';go(state.tab,false);}else setSeason(+e.target.value,false);});
  $('#theme').addEventListener('change',applyTheme);
  $('#gridSort').addEventListener('change',e=>{state.gridSort=e.target.value;drawGrid();});
  $('#gridMin').addEventListener('change',e=>{state.gridMin=+e.target.value;drawGrid();});
  $('#gridFind').addEventListener('input',e=>{state.gridFind=e.target.value;drawGrid();});
  $('#eraStrip').addEventListener('click',e=>{const s=e.target.closest('[data-era]');if(s)setEra(state.era===s.dataset.era?'all':s.dataset.era);});
  $('#eraStrip').addEventListener('pointerenter',()=>{tourPause();},{passive:true});$('#eraStrip').addEventListener('pointerleave',()=>{if(!tour.stopped)tourStart();},{passive:true});
  $('#eraStrip').addEventListener('mouseover',e=>{const s=e.target.closest('[data-era]');if(s&&!tour.stopped){drawEraStrip(s.dataset.era);}});
  if('IntersectionObserver' in window){new IntersectionObserver(en=>{tour.visible=en[0].isIntersecting;if(tour.visible)tourStart();else tourPause();},{threshold:.2}).observe($('#eraStrip'));}else{tour.visible=true;tourStart();}
  $('#circuits').addEventListener('click',e=>{const b=e.target.closest('[data-cid]');if(b){state.ground=b.dataset.cid;go('grounds');}});
  const clear=t=>{if(t==='nations')state.nation=null;if(t==='players')state.player=null;if(t==='grounds')state.ground=null;if(t==='coaches')state.coach=null;};
  $('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;clear(b.dataset.tab);go(b.dataset.tab,false);});
  $('#view').addEventListener('click',e=>{const a=e.target.closest('[data-nation],[data-player],[data-ground],[data-coach],[data-match],[data-year],[data-tab]');if(!a)return;if(a.tagName==='A')e.preventDefault();
    if(a.dataset.tab){clear(a.dataset.tab);go(a.dataset.tab,false);return;}
    if(a.dataset.year){const y=+a.dataset.year;ensureYearInLens(y);state.whole=false;state.year=y;fillSeasons();applyTheme();drawRiver();state.match=byYear[y].matches.slice(-1)[0]?.id;go('season',false);return;}
    if(a.dataset.match){openMatch(+a.dataset.match,false);return;}
    if(a.dataset.nation){state.nation=a.dataset.nation;go('nations',false);return;}
    if(a.dataset.player){state.player=a.dataset.player;go('players',false);return;}
    if(a.dataset.ground){state.ground=a.dataset.ground;go('grounds',false);return;}
    if(a.dataset.coach){state.coach=a.dataset.coach;go('coaches',false);return;}});
  $('#view').addEventListener('change',e=>{const t=e.target;if(t.id==='lens'){state.lens=t.value;render();}else if(t.id==='plens'){state.plens=t.value;render();}else if(t.id==='heatMetric'){state.heat=t.value;render();}else if(t.id==='duelBy'){state.duelBy=t.value;state.dA=state.dB=null;render();}else if(t.id==='dA'){state.dA=t.value;render();}else if(t.id==='dB'){state.dB=t.value;render();}});
  $('#view').addEventListener('input',e=>{if(e.target.id==='find2'){state.find2=e.target.value;const pos=e.target.selectionStart;render();const f=$('#find2');if(f){f.focus();f.setSelectionRange(pos,pos);}}});
  const src=$('#sources');if(src)src.addEventListener('click',()=>{$('#sourcesBox').open=true;$('#sourcesBox').scrollIntoView({behavior:RM?'auto':'smooth'});});
  let rt;addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(()=>{drawRiver();if(state.tab==='season')render();},150);});
}
init();
